quests[13411] = { id = 13411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", progress = "Return to me after you have helped capture each fort!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", sourceObjectiveStatus = "unverified-source-field" }
quests[13412] = { id = 13412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corastrasza", description = "Greetings, {class}. Might I impose on you for a favor?\n\nCorastrasza is the sister of Raelorasz - the red dragon in charge of our outpost here. Against his will, she has ascended to one of the upper rings of the Nexus to observe some frighteningly powerful blue drakes.\n\nThough he will never say it, he worries about her, and would welcome any news of her well-being.\n\nPlease seek her out. Ask her to put her pride aside and send word to her brother.", sourceObjective = "Librarian Serrah wants you to speak to Corastrasza in Coldarra.", completion = "It's quite presumptuous of you to interfere in the personal affairs of a dragon, don't you think, {race}?\n\nThat aside, it would be wrong of me not to let my brother know that I am well. You may tell your meddling friend that I will keep my brother abreast of my actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[13413] = { id = 13413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aces High!", description = "You possess the courage to draw so near to Malygos' lair, mortal? Or is it simply ignorance? Soon we shall know....\n\nI am a seasoned trainer of the graceful drakes of the red dragonflight. My business here is to study the enemy and teach my precious pets the tactics that will be most effective when we face the master of the blues.\n\nTo demonstrate your nerve and ability, I will allow you to ride one of my drakes against the enemy's minions.\n\nThe opportunity is yours for the asking...", sourceObjective = "Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.", progress = "Well, mortal, what do you think of my pets?", completion = "My drake tells me that with practice, you might become a capable combatant.\n\nVery well, then. In the interest of our war on Malygos, I shall allow you to practice with my pets at your leisure.\n\nMake ready, {race}, for he is a fierce and unforgiving opponent.", sourceObjectiveStatus = "unverified-source-field" }
quests[13414] = { id = 13414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aces High!", description = "Again we meet, {race}. I confess, your presence is beginning to grow on me.\n\nAm I correct in assuming that you've come to hone your aerial combat skills?\n\nAs always, my pets stand ready to bring fiery destruction to the enemy.\n\nSpeak, and they shall be at your disposal.", sourceObjective = "Corastrasza on the upper ring of the Nexus in Coldarra wants you to ride her drake and kill 5 Scalesworn Elites.", progress = "Yes, {race}?", completion = "I noticed some improvement today, {class}. At moments, it was as if you were one with the drake.\n\nYou are welcome to practice with my precious pets at your leisure.", sourceObjectiveStatus = "unverified-source-field" }
quests[13415] = { id = 13415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, use the disk to recover the shell. Hopefully, Mimir hasn't decided to put any more obstacles in our way.", sourceObjective = "Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library.", progress = "The console appears to have an opening for the inventor's disk.", completion = "<You insert the disk into the console. Suddenly, lights on its surface illuminate and a mechanical voice speaks.>\n\nInventor's disk authenticated. Welcome back, Keeper Mimir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13416] = { id = 13416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Library Console", description = "Norgannon's shell is within our reach, {name}. Take the inventor's disk into the library's interior. There should be a console there that you can activate with the disk. I imagine Mimir stored more there than just Norgannon's shell. There are probably enough schematics stored there to keep Ironforge's engineers occupied for years!\n\nAnyway, bring the disk to the console. Hopefully, Mimir hasn't decided to put any more obstacles in our way.", sourceObjective = "Take the Inventor's Disk to the Inventor's Library Console inside the Inventor's Library.", progress = "The console appears to have an opening for the inventor's disk.", completion = "<You insert the disk into the console. Suddenly, lights on its surface illuminate and a mechanical voice speaks.>\n\nInventor's disk authenticated. Welcome back, Keeper Mimir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13417] = { id = 13417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Bronzebeard", description = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here.\n\nHop on my flying machine and help keep us covered from those iron dwarves on the way out!You will be able to choose one of these rewards:", sourceObjective = "Accompany Brann Bronzebeard and his flying machine to Frosthold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13418] = { id = 13418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nYou may have heard rumors of our failure in assaulting the glacier from the ground, but let me set those concerns to rest. We're now mounting our assault from one of the most advanced pieces of engineering known to Azeroth, the Skybreaker. The Horde don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart.", sourceObjective = "Speak to Officer Van Rossem to secure passage to the Skybreaker in Icecrown, and then report to High Captain Justin Bartlett.", completion = "Welcome to the Skybreaker.\n\nFrom here we are laying our groundwork for the assault on Arthas. There's a lot of work to be done, but before we can get into the real meat of it, we want to make sure that the Argent Crusade is adequately reinforced - we're going to need their help later.\n\nIf you have not already, speak to Absalan the Pious on the main deck.", sourceObjectiveStatus = "unverified-source-field" }
quests[13419] = { id = 13419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for War", description = "You there!\n\nYou look like you have some wits about you. We could use some more able bodies in Icecrown.\n\nThe Alliance scum rushed into Icecrown ahead of us, unprepared, and got just what they deserved for their impatience. We took our time, we made ready, and soon we will mount a true assault from one of the most advanced pieces of engineering known to Azeroth - Orgrim's Hammer. The Alliance don't stand a chance, and neither does Arthas.\n\nSpeak to me when you're ready to depart and lend a hand.", sourceObjective = "Speak to Sky-Reaver Klum to secure passage to Orgrim's Hammer in Icecrown, and then report to Sky-Reaver Korm Blackscar.", completion = "Welcome to Orgrim's Hammer.\n\nFrom here we are laying our groundwork for the assault on Arthas. There's a lot of preparation to be done, but before we can get into the real meat of it, we want to make sure that the Argent Crusade is adequately reinforced - we're going to need their help later.\n\nIf you have not already, speak to Brother Keltan on the main deck.", sourceObjectiveStatus = "unverified-source-field" }
quests[13420] = { id = 13420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everfrost", description = "This piece of ice has been submitted to immense pressures and exposed to natural magics from deep beneath the world's surface. In combination, these effects have yielded an ice that will never melt.\n\nKnowing little of these things, you resolve to bring the sample back to Dun Niffelem. Someone there is bound to be familiar with its properties.", sourceObjective = "You are to return to Dun Niffelem and ask Calder about the piece of Everfrost.\n\nProvided item:", completion = "<The reflection of the everfrost sparkles in Calder's eye as he holds it aloft.>\n\nAhh, everfrost. The symbol of the heart of our people...\n\nEverfrost was once plentiful in this region. Over the ages, though, the jormungar have devoured nearly all of it. It is now very rare and very precious to my people.\n\nAs you roam these lands, keep a lookout for more pieces of everfrost. Return to me with any that you find and we will be most grateful.", sourceObjectiveStatus = "unverified-source-field" }
quests[13421] = { id = 13421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember Everfrost!", progress = "Have you discovered any more everfrost, little {race}?", completion = "Well done, little {class}.\n\nEverfrost was once plentiful in this region. Over the ages, though, the jormungar devoured nearly all of it. It is now very rare and very precious to my people.\n\nAs you roam these lands, keep a lookout for more pieces of everfrost. Return to me with any that you find and we will be most grateful." }
quests[13422] = { id = 13422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining Discipline", description = "You've succeeded where others have failed.  Yet you cannot rest on your laurels.\n\nYou must show others what strength and commitment really mean.\n\nThe male insubordinates inside the Forlorn Mine need to be disciplined once again.  Show them sister... show them what it means to disobey us.", sourceObjective = "Gretta the Arbiter in Brunnhildar Village wants you to use the Disciplining Rod on 6 Exhausted Vrykul inside the Forlorn Mine.", progress = "Hail, sister.", completion = "You continue to lead by example.  We look up to you, sister.", sourceObjectiveStatus = "unverified-source-field" }
quests[13423] = { id = 13423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Your Title", description = "Everyone's impressed by your performance, sister.  But do not let your guard down -- every new challenger with delusions of grandeur is going to come out swinging for your title of Hyldskvinnar.\n\nShow these upstarts what you're made of.", sourceObjective = "Gretta the Arbiter in Brunnhildar Village wants you to defeat 6 Victorious Challengers.", progress = "Your power humbles us, sister.", completion = "You continue to prove yourself worthy.  We are honored by your presence.", sourceObjectiveStatus = "unverified-source-field" }
quests[13424] = { id = 13424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Pit", description = "To truly stay in your best riding shape you'll want to test yourself against the other Hyldnir every day.\n\nHead back into the Pit of the Fang and show them what you're capable of.  They'll appreciate suffering defeat to one as skilled as yourself.", sourceObjective = "Gretta the Arbiter, in Brunnhildar Village, wants you to use the Reins of the Icemaw Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.", progress = "Hail, sister.", completion = "You continue to demonstrate your prowess.  Your sisters have not lost their respect for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13425] = { id = 13425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aberrations Must Die", description = "It is not enough to demonstrate your prowess among your peers.  You must also fight our enemies, dear sister.\n\nThe Valkyrion traitors continue to mock our noble drake-riding traditions by rearing plagued proto-drakes.\n\nSeize the frost oil they wield and use it to freeze their abominable plagued eggs.", sourceObjective = "Gretta the Arbiter in Brunnhildar Village wants you to go to Valkyrion and obtain Vials of Frost Oil from the Valkyrion Aspirants. Use the Vials of Frost Oil to destroy 30 Plagued Proto-Drake Eggs.", progress = "Did you destroy the blighted eggs?", completion = "A leader in more ways than one.  We thank you, sister.", sourceObjectiveStatus = "unverified-source-field" }
quests[13426] = { id = 13426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xarantaur, the Witness", description = "It seems we're not the only visitors to this area. A courier relayed a message from a tauren named Xarantaur, who said he was visiting a taunka village called Camp Tunka'lo. The note was somewhat cryptic, but it seems this Xarantaur has come to Storm Peaks to learn the history of a taunka legend.\n\nMeet up with him, {name}. See if what he knows can help us in any way. From his description, Camp Tunka'lo is far to the east, beyond the Terrace of the Makers and north of Dun Niffelem.", sourceObjective = "Speak with Xarantaur at Camp Tunka'lo.", completion = "So Boktar received my note? That's excellent news. I doubted the taunka longrummer who carried it would reach anyone.", sourceObjectiveStatus = "unverified-source-field" }
quests[13427] = { id = 13427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", sourceObjective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13428] = { id = 13428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", sourceObjective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", sourceObjectiveStatus = "unverified-source-field" }
quests[13429] = { id = 13429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", sourceObjective = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", progress = "<Xi'ri acknowledges your presence.>", completion = "<Xi'ri pulses with energy as you feel an object materialize in your hands.  It is the medallion you gave to A'dal on Akama's behalf, its power augmented by the naaru's magic.  The Sha'tar have entrusted you with the Medallion of Karabor, and with it access to the Black Temple.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13430] = { id = 13430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of the Naaru: Magtheridon", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", sourceObjective = "A'dal in Shattrath City wants you to slay Magtheridon.", completion = "You have proven yourself as a being of great power. The naaru approve...", sourceObjectiveStatus = "unverified-source-field" }
quests[13431] = { id = 13431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cudgel of Kar'desh", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!", sourceObjective = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths...", sourceObjectiveStatus = "unverified-source-field" }
quests[13432] = { id = 13432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vials of Eternity", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.", sourceObjective = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.", progress = "I've asked the impossible of you, yet I expect you to succeed.  Much depends on it.", completion = "The power contained even in this small amount of water from the Well of Eternity is incredible.\n\nI can see clearly into every moment in time linked to Hyjal... the creation of the second Well of Eternity, Illidan's imprisonment, the enchantment of the World Tree and... yes!  The Battle of Mount Hyjal.\n\nWe must make haste, the timeline is not safe.", sourceObjectiveStatus = "unverified-source-field" }
