quests[13501] = { id = 13501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[13502] = { id = 13502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tisket, a Tasket, a Noblegarden Basket", description = "Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.", sourceObjective = "The Noblegarden Vendor wants you to collect 10 Noblegarden Chocolates and return them along with the Borrowed Egg Basket.", progress = "Do you have the ten Noblegarden Chocolates?", completion = "Well done! And here, please... keep the basket!\n\nRemember, you can always return with more Noblegarden Chocolates to trade for additional items.", sourceObjectiveStatus = "unverified-source-field" }
quests[13503] = { id = 13503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tisket, a Tasket, a Noblegarden Basket", description = "Here... take this Egg Basket and go hunting for Brightly Colored Eggs. Return to me with the basket when you've found ten Noblegarden Chocolates.", sourceObjective = "The Noblegarden Merchant wants you to collect 10 Noblegarden Chocolates and return them along with the Borrowed Egg Basket.", progress = "Do you have the ten Noblegarden Chocolates?", completion = "Well done! And here, please... keep the basket!\n\nRemember, you can always return with more Noblegarden Chocolates to trade for additional items.", sourceObjectiveStatus = "unverified-source-field" }
quests[13504] = { id = 13504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatterspear Laborers", description = "There are a large number of Shatterspear trolls picking through the ruins to the north and northeast. I suspect that they're looking for magical artifacts, but none of our scouts have reported the discovery of anything of significance turning up from their digs. They may well just be fueling their war.\n\nOne thing is fairly certain though: less laborers would slow down their offensive, so less laborers is what they're going to get. You in?", sourceObjective = "Kill 10 Shatterspear Laborers.", completion = "Good work. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13505] = { id = 13505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of the Highborne", description = "There are several ruins similar to these spread through Darkshore, many of them inhabited by the troubled spirits of the Highborne. Out of mild courtesy for their cursed souls, we haven't been overly proactive about stripping the ruins of artifacts, but those hesitancies vanish in light of this new troll threat.\n\nWhile you're aiding the Sentinels in their goals within the ruins, please collect any artifacts that you stumble upon and bring them back to me. I would like to preserve what little I can.", sourceObjective = "Retrieve 8 Highborne Relics.", progress = "Were you able to recover any artifacts?", completion = "Perfect! Thank you so much. I would hate to lose more records of our culture to war - far too much has been sacrificed already.", sourceObjectiveStatus = "unverified-source-field" }
quests[13506] = { id = 13506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reason to Worry", description = "These appear to be orders dispatched to the overseers at the ruins from a superior in the Shatterspear War Camp. Most of the document contains negligible strategic value, but a couple lines stick out to you.\n\n\"We captured another night elf spying on our operation. She has been taken back to the camp to be tortured for more information. Keep an eye out for additional spies - we cannot afford for our operation to be compromised.\"\n\nThe Lieutenant will surely want this information.", sourceObjective = "Bring the Shatterspear Orders to Lieutenant Morra Starbreeze at the Ruins of Mathystra.", progress = "Yes, {class}?", completion = "\"Another?\" They have more than one. I will not leave any of my people to be tortured, we must act quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13507] = { id = 13507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denying Manpower", description = "To the north, the Shatterspear have a war camp where they are constructing their catapults. The camp is guarded by some of their mystics, but I've started receiving reports that there are sightings of orcs and tauren there as well.\n\nI don't want to make any assumptions as to what that suggests, but I do want you to go in and kill them before they can make any further strikes on our Sentinels.", sourceObjective = "Kill 6 Horde Enforcers and 6 Shatterspear Mystics.", progress = "Have you finished the deed?", completion = "Excellent work. One more threat we can worry a bit less about. We'll continue the offensive while they are still off-guard.", sourceObjectiveStatus = "unverified-source-field" }
quests[13508] = { id = 13508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Response", description = "I have a scout that we lost contact with a couple days ago. I assumed her dead, but it appears that she's been captured. The trolls indicate that they have at least two captives though... the only other person that comes to mind is Alanndarian Nightsong, a civilian that was in the area against my advisement early yesterday.\n\nThe Shatterspear have established a war camp to the north - it is almost certainly where any of their prisoners are being taken. Find them and free them if you're able.", sourceObjective = "Locate the night elf prisoners at the Shatterspear War Camp.", completion = "<Alanndarian looks very pale, though shallow breaths betray the life that remains in her.>\n\nYou're here...  to save me? A bit later... than I hoped.", sourceObjectiveStatus = "unverified-source-field" }
quests[13509] = { id = 13509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Supplies", description = "The trolls are building their forces and supplies at the war camp to the north. When they feel they are ready, they will almost certainly launch their attack on Lor'danel from that location. It shouldn't take us long to rout this rabble, but I'm not one for taking unnecessary risks.\n\nI want you to fight your way into the war camp and set fire to any stockpiles of supplies that you see. The setback should buy us quite a bit of time before they can muster a counterattack.", sourceObjective = "Destroy 12 Shatterspear Armaments.", completion = "Excellent work. That should slow them down a bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13510] = { id = 13510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timely Arrival", description = "It's good to see you. I wasn't looking forward to enduring what Alanndarian did, so the rescue is somewhat welcome.\n\nI saw the troll leader before I was captured, and thought I had the perfect opportunity to kill him, but he's protected by some sort of magic shield. Morra needs to know before she mounts her assault, but first, we need to get out of here.\n\nHelp me to the dock - I'll make my way to Lor'danel via water, and you can go back to Morra with the intel.", sourceObjective = "Escort Sentinel Aynasha to safety.", completion = "Some sort of shield you say? We might have a way around that. Balthule had an idea for breaking whatever protective enchantments their shaman had, so it might work on this too. Thank you for saving Aynasha and bringing me this information - it may well make the difference in our battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[13511] = { id = 13511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Bitter Wish", description = "Morra sent you? I should have listened to her - it's just hard to take trolls seriously I guess.\n\n<Alanndarian lets out a weak chuckle.>\n\nIt's way too late for that anyway. We're mortal now... this is the fate we have to face, one way or another. I've had time to accept that.\n\nI have one request though... kill the torturer that did this to me. They call him Rit'ko... you can find him just ahead with the other prisoner.\n\n<Alanndarian offers a small smile, then winces and slumps back over in pain.>", sourceObjective = "Kill Rit'ko, the Shatterspear Torturer.", completion = "Alanndarian is dead then. That saddens me greatly, but it is not entirely unexpected. I expect no mercy from these savages, and will show them none.", sourceObjectiveStatus = "unverified-source-field" }
quests[13512] = { id = 13512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Strikes", description = "Striking at the head of the beast doesn't work if there's another head to replace it. Before we can kill their leader, we need to kill the subleaders that may try to step up. Right now, they are not as well defended, and you should be able to best them without much support.\n\nTake this dryad spear and hunt them down. The poison on its tip should slow their incantations. My scouts reported one inside the water chamber in the ruins to the east and the other past the remains of the tower to the southwest.", sourceObjective = "Kill Sheya Stormweaver and Lorenth Thundercall.", completion = "You've shown a great deal of talent for one so young. Good work. It seems the final battle is before us.", sourceObjectiveStatus = "unverified-source-field" }
quests[13513] = { id = 13513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Brink", description = "I've already been working on something for breaking down their protective wards. With a focus based in their power and a bit of druidic magic, we should be able to breach their shields.\n\nFind their shaman to the east and southeast and recover several of their amulets. I will prepare them and imbue an arrow that you can deliver to Sandrya Moonfall for the attack.", sourceObjective = "Retrieve 6 Shatterspear Amulets.", progress = "Did you recover the amulets?", completion = "These will do perfectly. I will prepare them for Sandrya - you are sure to be dispatched to meet with her shortly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13514] = { id = 13514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancients' Ire", description = "Come to join the offensive? If you're looking for Sandrya Moonfall, she's leading the attack on the Shatterspear leader at the cave in the back of the vale, you can meet her there.\n\nWhile you're here though, we could certainly use your help with routing the rest of their tribe. Go ahead and take the company of one of the Vengeful Protectors there and see to it that every last building is destroyed and every last troll killed. We can't have them coming back for revenge when we're less prepared, can we?", sourceObjective = "Utilize a Vengeful Protector to kill 30 Shatterspear trolls and destroy 6 Shatterspear Structures.", progress = "I have no yearning for war, but I've had sufficient reason to worry that we'd get rusty after so much time away from the front lines. It's good to see that the Sentinels and the ancients are every bit as dangerous as I remember them.", completion = "You performed excellently up there! We are fortunate to have you with us.\n\nI haven't yet received word regarding their leader. If you haven't spoken with Sandrya at the cave in the back of the vale, be sure to do so before you depart.", sourceObjectiveStatus = "unverified-source-field" }
quests[13515] = { id = 13515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Threat", description = "Their leader and his guard are before us. My Sentinels are ready to take care of his guard, we only awaited this arrow to seal their leader's fate.\n\nLet me know when you are prepared to attack. As soon as my Sentinels engage, I will shatter the leader's shield, and we will assault him together. Strike swiftly and we can rout this threat to our lands here and now.\n\nWe await only you - speak to me when ready.", sourceObjective = "Speak to Sandrya Moonfall to start the attack, and aid her in killing Jor'kil the Soulripper", progress = "As it should be.", completion = "We owe a great debt to you for all that you've done to see this battle through.\n\nNot often can we claim victories so decisively, but it seems there's far more to this plot than just the Shatterspear. If you haven't already checked his body for information, make sure to do so before you leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[13518] = { id = 13518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Wave of Survivors", description = "It's too late for Laird, he didn't make it in time.\n\nThe last wave of night elves from Auberdine attempted to escape a couple of hours ago. They stayed in their old home, clinging to the hope that it could be salvaged, but it seems they were finally forced out. I fear many of them won't make it, like Laird did not.\n\nQuickly, go down the coast to the west and find any survivors that you can. We're sending Sentinels and Hippogryphs down, but every moment counts - we need to know which ones might make it.", sourceObjective = "Locate any refugees from Auberdine that are still alive.", progress = "Their pride kept them in Auberdine for this long, but none deserve such a cruel fate.", completion = "Thank you, {class}. Some of them surely would not have made it without you.\n\nWe'll be taking the wounded to the main building once we have them all safely back in town. Perhaps you can meet us there later?", sourceObjectiveStatus = "unverified-source-field" }
quests[13519] = { id = 13519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight's Hammer", description = "A group of Twilight's Hammer cultists has set up camp southwest of here.  They're preparing an army of water elementals to use against Lor'danel.\n\nTheir leader, High Cultist Azerynn, has pacts with the dark Old Gods that grant his sect power over the elements.  Go and deal with them before it's too late, {name}.\n\nThe cataclysm has left the elemental spirits in disarray... it's only a matter of time until they have enough elementals to overcome our defenses.", sourceObjective = "Slay High Cultist Azerynn and 10 Twilight Fanatics in the Twilight Encampment.", completion = "You've done well, {name}.  The Twilight's Hammer is a dangerous cult.  It would be foolish to underestimate the danger they represent.", sourceObjectiveStatus = "unverified-source-field" }
quests[13520] = { id = 13520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of the Seas", description = "It is good to see you. You were key in ensuring that our loved ones made it home, and I hold some hope that you may yet help us further.\n\nLike Laird, their wounds will be grave - every one of them battered by the coast and assaulted by the elementals. I am doing what I can, but it seems that those elementals hosted a toxin that is weakening their ability to heal. I believe I can concoct a salve, but I will need secretion from the muscles of the clams that inhabit this coast. Can you help me?", sourceObjective = "Collect 16 Encrusted Clam Muscles.", progress = "Did you bring muscles from the clams? I worry that our time grows very short.", completion = "This will do perfectly. Thank you so much!\n\nI suspect they will want to thank you personally should they recover, so perhaps you can stop by later on.", sourceObjectiveStatus = "unverified-source-field" }
quests[13521] = { id = 13521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzbox 413", description = "Greetings!\n\nI'm helping Tharnariun here try to unravel what's been corrupting the wildlife in the area. I've set up some machines in the field that can analyze animal parts and possible corruption agents. If you can get me some good samples, we can get to the bottom of this affliction quickly.\n\nThe first machine is Buzzbox 413. I set it up on the beach just east of town. I'll need you to gather some flesh from the nearby corrupted tide crawlers and bring it to the machine so that I can analyze it.", sourceObjective = "Gather 4 Corrupted Tide Crawler Flesh samples and bring them to Buzzbox 413 for analysis.", progress = "<Buzzbox 413 hums at you expectantly.>", completion = "<The machine crackles loudly, and then Wizbang's static-ridden voice becomes audible.>\n\nLovely! I hope you didn't kill too many of them. We're not trying to wipe out the population, we just need to get to the source of this corruption quickly! I'm proceeding with the analysis now.", sourceObjectiveStatus = "unverified-source-field" }
quests[13522] = { id = 13522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat from the Water", description = "Some of the survivors of this last Auberdine attack are still trying to make it up the coast to safety. We only caught word that they were coming within the last hour. I wish that we had more warning...\n\nThe coastline west of us is swarming with vile spray, vicious little water elementals. We need to clear them out if any of the survivors are to have a chance of making it to Lor'danel. Depart immediately and kill every elemental you see.", sourceObjective = "Kill 8 Vile Spray.", progress = "Have you cleared the coast?", completion = "Your efforts are very much appreciated. Since the Cataclysm, the elementals have been out of control. We have little hope of taking back Auberdine without extinguishing their presence first.", sourceObjectiveStatus = "unverified-source-field" }
quests[13523] = { id = 13523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Over the Tides", description = "Do not worry about me.  My wounds are deep and death will soon come to me.\n\nIt is all up to you now... you must stop the Twilight's Hammer.\n\nThe Old Gods they worship have granted them power over the restless water spirits... but that power is tenuous.  Channel Elune's presence through this orb once the elementals have been defeated.\n\nUse the power of Elune to banish the spirits permanently.", sourceObjective = "Use the Orb of Elune on the remains of 6 Enraged Tidal Spirits.", progress = "My lifeforce abandons me... even now...", completion = "You've succeeded... it hasn't all been in vain...\n\nMy time approaches.  Go now, {name}, and may Elune protect you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13524] = { id = 13524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Silverbrook", description = "You... you're not one of them?  Quick!  Let me out!\n\nWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!You will be able to choose one of these rewards:", sourceObjective = "Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook. Report to Lieutenant Dumont when you reach Amberpine Lodge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13525] = { id = 13525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Happening to the Blackwood Furbolg?", description = "Our ancestors lived alongside the Blackwood furbolgs for generations. But recently, we have lost contact with their settlements deeper in the forest. One of their larger villages, Blackwood Hold, can be found to the south.\n\nTravel there and find Elder Brolg. Ask him why his people have withdrawn from us and offer your help, if necessary.", sourceObjective = "Speak with Elder Brolg at Blackwood Hold.", completion = "Why have you come here, outsider?\n\n<You tell the elder that you were sent by Foriel Broadleaf at the Grove of the Ancients. He seems to relax slightly.>\n\nThe elf is right. The forces of Felwood have seeped into Darkshore and sickened my people.", sourceObjectiveStatus = "unverified-source-field" }
quests[13526] = { id = 13526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear's Paw", description = "The foul satyr of Felwood have started to introduce their poison into Darkshore, into our lands. Their corruption kills the land and twists the creatures who live in it. My people are no exception.\n\nOur magic alone is not enough to bring them back to their senses. There is an herb, called bear's paw, that we use to break fevers and fortify the weak. With its help, we may be able to break the influence of the satyr. The herb grows in the wilds around the village.", sourceObjective = "Bring 8 stalks of Bear's Paw to Elder Brolg at Blackwood Hold.", progress = "Have you gathered the bear's paw?", completion = "These are poor, weak stalks, but they are all we have. The corruption spreads quickly, even among the plants of the forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13527] = { id = 13527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Accounting for Taste", description = "<The machine buzzes for a few moments  before Wizbang's voice breaks through.>\n\nInteresting! The source of this corruption definitely came from something external--no surprises there--but it appears that in this case they've been eating something foul. A large mammal probably. Most likely a bear.\n\nSearch the beach for a bear carcass for me. Slightly east of there would make the most sense, on the inland side of the beach. Bring me the sample back at town.", sourceObjective = "Retrieve a sample from a decomposing bear carcass east of Buzzbox 413.", progress = "Welcome back! Did you find that bear sample that I was looking for?", completion = "This definitely looks like the stuff they were eating. Let me take a closer peek...", sourceObjectiveStatus = "unverified-source-field" }
quests[13528] = { id = 13528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzbox 723", description = "There are a couple other forms of wildlife that we've verified infected. It's actually good news that the crabs appear to have caught this from the bears - hopefully that means this all stems from one source. We need to focus our attention on those bears now.\n\nBuzzbox 723 is near the waterfalls to the east. It's going to be messy work, but it's necessary - I'll need you to bring some fresh bear guts to that buzzbox for analysis. We'll go from there once I have the information.", sourceObjective = "Gather 6 samples of Corrupted Thistle Bear Guts and bring them to Buzzbox 723 for analysis.", progress = "<Buzzbox 723 hums at you expectantly.>", completion = "<Static precedes Wizbang's distorted voice.>\n\nThe results are coming in now. We should have some information on how the bears contracted this in just a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[13529] = { id = 13529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corruption's Source", description = "I rushed here as soon as I heard the news from Wizbang. I know who's behind this mess now. Zenn Foulhoof.\n\nHe came over from Teldrassil after he was chased out for performing perverse magics. The kinds of corruption he employs are not welcome among my people, and it seems he's taken it a step further this time, perhaps as some form of revenge.\n\nZenn's been given too many chances, it's time we remove this threat to all that is natural. Kill Zenn and his minions, and then find me back in Lor'danel.", sourceObjective = "Kill Zenn Foulhoof and 8 Vile Grell in Cliffspring Hollow.", progress = "This is never desirable work. Zenn was not always the corrupt being that you now see. Sadly, he is behind reproach at this point. Much of the damage that he has done to nature is irreversible.", completion = "It is done then. Thank you. I only hope that the wildlife here will see more peace with his passing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13537] = { id = 13537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste for Grouper", description = "Between boat rides and building, I'm exhausted... and hungry. You know what sounds tasty? Fish. Fish sound delicious.\n\nDarkshore is known for its grouper. If you fish me up some, I'll make it worth your time.", sourceObjective = "Use your fishing skill to obtain 4 Darkshore Grouper.", progress = "<Johnathan's belly grumbles as you approach.>\n\nCouldn't have said it better with words.", completion = "It looks like fishing's your thing. My belly appreciates the gift.\n\nI'm thinking you would get more use out of this pole than I would. Have at it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13538] = { id = 13538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Southern Sabotage", description = "The three towers south of the Wintergrasp river are draining power from the Fortress! \n\nDestroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!", sourceObjective = "Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower and return to Tactical Officer Ahbramis in Wintergrasp.", completion = "I heard the explosion from here! Excellent job - we've already begun rerouting the power into the Titan relic to super-charge our own forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[13539] = { id = 13539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toppling the Towers", description = "While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious.\n\n\"Attack him where he is unprepared, appear where you are not expected.\"\n\n{name}, I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops.\n\nReturn to me once you've destroyed a tower.", sourceObjective = "Destroy Shadowsight Tower, Flamewatch Tower, or Winter's Edge Tower and return to Tactical Officer Kilrath in Wintergrasp.", progress = "My disgust for Warlocks is only exceeded by my hate for the undead. However, they can both prove useful at times.", completion = "Now in order to kill the enemy, our men must be roused to anger; that there may be advantage from defeating the enemy, they must have their rewards. I hope that these are sufficient for your service to the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13542] = { id = 13542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Wind", description = "If we're going to take the Ruins of Auberdine back from the Twilight's Hammer, the elementals that they've summoned must be dealt with on a permanent basis.\n\nThat's where you come in.\n\nLook, I don't expect you to retake the town, but while we're healing up here, you can soften them up for us.\n\nTo permanently deal with the frenzied cyclones, head west, kill them, take their bracers, and put them in the moonwell. That will destroy the bracers and keep those elementals from being resummoned.", sourceObjective = "Use the moonwell in the Ruins of Auberdine to destroy 8 sets of Frenzied Cyclone Bracers.", completion = "I cannot thank you enough, {name}. Now we'll have a fighting chance to retake the ruins as soon as we are in better health.", sourceObjectiveStatus = "unverified-source-field" }
quests[13543] = { id = 13543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Hammers to Break", description = "I've flown through the ruins of Auberdine on a scouting mission. There are three Twilight's Hammer cultists that are responsible for the elementals that have overrun the destroyed town.\n\nHead west into the ruins. Seek out and slay Cloudtamer Wildmane, Windmaster Tzu-Tzu, and Skylord Braax.\n\nOnly then will Sentinel Selarin and her forces stand a chance of taking back their home.", sourceObjective = "Slay Cloudtamer Wildmane, Windmaster Tzu-Tzu, and Skylord Braax.", completion = "Without those three coaxing them, perhaps the flow of elementals into the Ruins of Auberdine will be stemmed.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13544] = { id = 13544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear's Blessing", description = "Before the bear's paw can be used to cleanse the afflicted, it must be completed and blessed. To the north of the village roams a tallstrider named Fleetfoot. You'll need its tailfeathers to complete the herb bundle.\n\nBring the tailfeathers and the bear's paw bundle to the ancient bear statue in the ruins around the Grove of the Ancient, further north of where you'll find Fleetfoot.\n\nWhile at the shrine, combine the tailfeathers with the bear's paw and receive the bear spirit's blessing.", sourceObjective = "Elder Brolg at Blackwood Hold wants you to bring him the Blessed Herb Bundle.", progress = "Have you visited the old bear statue?", completion = "<Elder Brolg accepts the blessed bundle from you and looks over it.>\n\nThis is exactly what we needed. The bear's spirit favors us and there may be hope for my brothers after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[13545] = { id = 13545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Afflicted", description = "With the sacred herbs and the bear's blessing, you must use this herb bundle to cleanse my brothers. The corruption spilling over from Felwood has driven them mad and they will attack any who come near. Expect the afflicted Blackwood to be angry with you until you have slain the spirits of corruption that haunt them.\n\nWhen you have freed my brothers from their madness, return to me.", sourceObjective = "Elder Brolg wants you to use the Blessed Herb Bundle to cleanse 7 furbolg of Blackwood Hold and kill the Spirits of Corruption driving them mad.", progress = "Have your efforts and the bear's blessing cleansed my brothers?", completion = "You have done well. My people have begun to emerge from their madness, but they will fall back into it if we do not deal with the source of the corruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[13546] = { id = 13546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defiler", description = "The Jadefire satyrs of Felwood have found their way into Darkshore, tainting the land, water, and creatures they encounter. You've seen what their corruption has done to my people and their homes. If we do not turn back the satyrs, all of us will share that fate.\n\nWithin the cave to the east is Sharax the Defiler, the satyr responsible for the ills of the Blackwood. Slay him, {name}, and free us from his influence. Show the satyr that the Blackwood will not lay down and die so easily.", sourceObjective = "Elder Brolg at Blackwood Hold wants you to kill Sharax the Defiler.", progress = "Have you defeated the satyr who poisons our lands?", completion = "Thank you, {name}. You are a hero to my people. Without you, we would be doomed to madness and death. May the bear spirit always watch over you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13547] = { id = 13547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coaxing the Spirits", description = "Your friends back at the refugee camp are unaware of the true and imminent danger that the Twilight's Hammer cultists have already brought into the world.\n\nFor you to deal with that, we'll first need to get some help from the dead of Auberdine.\n\nSearch through the ruins of the town and find the corpses of Thundris Windweaver, Elissa Starbreeze, Taldan, and Caylais Moonfeather. Coax the spirits from their bodies and then return with them to me here.", sourceObjective = "Coax the spirits from Thundris Windweaver, Elissa Starbreeze, Taldan, and Caylais Moonfeather.", completion = "So much death and pain. Can there be any doubt that there is more yet to come?\n\nAll I wish to do is move onward into the Goddess's embrace as do these others.\n\nBut first, let us see if we can keep even more misery and destruction from being spread.", sourceObjectiveStatus = "unverified-source-field" }
quests[13548] = { id = 13548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[13549] = { id = 13549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tails Up", description = "Along with the Drakkari artifacts, I'm interested in returning to Zandalar with some of the Zul'Drak wildlife. I have males of both the frost leopards and icepaw bears, but I need females!\n\nToo bad that my trapper was killed in a most unfortunate accident. Perhaps you would be willing to fill in for him?\n\nPut the leopards and bears to sleep with this blowgun then lift their tails and return with some females if you would be so kind. They can be found near the Altars of Rhunok, Quetz'lun, and Har'koa.", sourceObjective = "Chronicler To'kini at Zim'Torga wants you to use To'kini's Blowgun on Frost Leopards and Icepaw Bears. Return to him with 3 females of each.", progress = "No, that just won't do. Please return when you have the female leopards and bears that I'll need for the arduous journey back home.", completion = "Very fine specimens indeed, {name}! These are sure to provide many hours of curious speculation amongst my colleagues back home.", sourceObjectiveStatus = "unverified-source-field" }
quests[13554] = { id = 13554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cure In The Dark", description = "<Some unintelligible speech spews forth from the machine before you make out Wizbang's voice again.>\n\nDuskrats! They've been eating the duskrats! Those little buggers only come from one place, a cave against the cliff-face to the east. Find a path up to the northeast and look for an opening under the waterfall.\n\nThe duskrats there are either getting into something nasty or someone's intentionally spreading some agent through them - in either case, just bring me back several samples of the stuff!", sourceObjective = "Retrieve 6 Samples of Foul Ichor from the creatures inside Cliffspring Hollow.", progress = "Did you get to the stuff? The sooner I can start working on a cure, the more animals we can save!", completion = "This should be plenty! Thanks so much! I'll get working on a cure for this nastiness immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[13556] = { id = 13556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eggs for Dubra'Jin", description = "How ya doin', mon? Thinkin' ya might be helpin' me out? Bah'Kini be needin' lots o' the raptor eggs to be sacrificin' to Dubra'Jin.\n\nHow ya thinkin' we not be overrun yet by the Drakkari? Dubra'Jin be lendin' us his aid!\n\nWe need ya to gather up the raptor eggs from around the trees outside here in Gundrak. Sometimes the raptors carry 'em to keep 'em warm, too.", sourceObjective = "Ha'wana at Dubra'Jin needs you to collect 12 Gundrak Raptor Eggs.", progress = "Who woulda thought the great Dubra'Jin be wantin' so many eggs? What he gonna do with them anyway?", completion = "One, two, three,... hehe, that be a good number o' them, mon! Now we be safe for quite some time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13557] = { id = 13557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearer of Good Fortune", description = "This key appears to be for the animal cages spread throughout Cliffspring Hollow. Tharnariun would surely appreciate if you took advantage of the situation to free some of the uncorrupted duskrats and thistle bears that are still being held captive.", sourceObjective = "Free 8 Uncorrupted Thistle Bears or Uncorrupted Duskrats from the cages in Cliffspring Hollow.", progress = "Yes, {race}?", completion = "I am pleased to hear that you were able to free some of the remaining wildlife. With a bit of good fortune, we will find the cure for the corruption that the others have faced before any more of them die.", sourceObjectiveStatus = "unverified-source-field" }
quests[13558] = { id = 13558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call Down the Thunder", description = "Aetherion is almost in our world, but he can still be dealt with!\n\nAt the end of the dock floats a ritual orb. I want you to use it to complete the ritual, beckoning the elemental lord down from his vortex.\n\nTrust me, {name}, I and the other spirits that you have freed will greatly weaken Aetherion. However, it will be up to you to finish him off for good and save the Kaldorei people of Darkshore from utter destruction.\n\nDeliver his essence to Corvine Moonrise at the refugee camp so he will know.", sourceObjective = "Use Aetherion's Ritual Orb and obtain Aetherion's Essence.", progress = "You have returned. What news do you bring?", completion = "Yalda? The spirits of others from the Ruins of Auberdine?\n\n<The druid ponders what you've conveyed about your adventure in the ruins.>\n\nI remember them all. They will be dearly missed, but they have moved on into the Goddess's embrace and that is for the best.\n\nAnde'thoras-ethil, may your troubles be diminished, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13559] = { id = 13559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Tribute", progress = "No ordinary tributes were good enough for the great Hodir when he walked among the frost giants.\n\nHe might not be with us anymore, but we've kept the tradition of offering tribute to his strength and wisdom.  It would do much for your renown to partake in this tradition, small {class}.", completion = "The Sons of Hodir accept your tribute, small one.  You continue to prove your worth as an ally in more ways than one." }
quests[13560] = { id = 13560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ocean Not So Deep", description = "You look like an able sort!\n\nThere are a great number of wrecks off of the coast here... most old, some new. For quite some time, I've been trying to get at their holds and put their valuables to more use, but there's a nasty infestation of murlocs that seem to have other ideas. I've sent scores of adventurers and none have returned.\n\nWorry not, I've learned my lesson, and that is not your fate. Swim to the due north and look for Gary. He'll explain the new plan. It's pretty simple really.", sourceObjective = "Gorbold Steelhand at Lor'danel wants you to speak to Gary for further instructions.", completion = "The decoys worked then? Great to hear it! Don't you worry yourself one bit about the treasures. Me and Gary will take care of the rest this time around.\n\nTruth be told, if something went wrong again and I lost any more of you adventurer types, I'm pretty sure they'd kick me out of town.", sourceObjectiveStatus = "unverified-source-field" }
quests[13561] = { id = 13561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solace for the Highborne", description = "I have come to Bashal'Aran to grant peace to the troubled spirits of the Highborne, but I find my hand hesitates with each blow. If you would like to aid me, you would have my gratitude.", sourceObjective = "Kill 6 Cursed Highborne and 6 Writhing Highborne.", progress = "Is it done?", completion = "You have my thanks. Though they may not be able to show it, you have the thanks of the Highborne spirits as well.\n\nFare safely, traveler.", sourceObjectiveStatus = "unverified-source-field" }
quests[13562] = { id = 13562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Flame of Bashal'Aran", description = "It is in times like these that we are forced to stop and examine our way of life. We are mortal now, and no matter how much we desire otherwise, we are deserving of our new place in this world.\n\nBashal'Aran, down the road to the south, once a city of our ancestors, it now is home to their cursed ghosts. We held hope of salvation for them as with ourselves, but we have left them in torment for too long. It is time to extinguish the Final Flame of Bashal'Aran.", sourceObjective = "Extinguish the Final Flame of Bashal'Aran.", completion = "You have our thanks. It is time that we leave the past behind us, and start looking to our future.", sourceObjectiveStatus = "unverified-source-field" }
quests[13563] = { id = 13563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Love Eternal", description = "I would like to extend my gratitude for saving us. I would call myself fortunate, but my beloved, Anaya, lays long dead. I am alone and deeply troubled, and sadly, I require your aid yet again.\n\nWandering the woods of Darkshore after my rescue, I found myself in the ruins of Bashal'Aran... where I saw the haunted spirit of my beloved.\n\nShe must be freed, but I lack the heart to do it. Her spirit must be destroyed.", sourceObjective = "Free the spirit of Anaya Dawnrunner and retrieve her pendant.", progress = "I somehow avoided being inflicted with the same toxin that the other survivors now endure. I cannot help but be envious of them to a degree though... living an eternity alone seems not worth living at all.\n\nI miss you so much, Anaya.", completion = "Thank you, {name}. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.\n\nPlease, I would be alone with my grief...", sourceObjectiveStatus = "unverified-source-field" }
quests[13564] = { id = 13564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Companion", description = "Please help... I can barely sit up.\n\nMy friend, a bear named Grimclaw, he's not here. I sent him ahead to let the Sentinels know we were coming before we left Auberdine, but he never arrived. I sensed something might be amiss as we were leaving, but with the evacuation, I never had a chance to act on it.\n\nIf he's injured, there's only one place that he would go - the Withering Thicket, north of Auberdine, down the road to the south from here. Bring him back to me safely... he's my only family.", sourceObjective = "Locate Grimclaw.", completion = "Greetings, traveler. You seem to have an interest in my friend here. You're here on behalf of his friend Volcor then I imagine? If Volcor didn't come himself, he must be injured as well. I hope he recovers quickly.\n\nGrimclaw is too injured to be moved far and he's going to need some immediate treatment. I'm afraid I can't let you take him back just yet, but perhaps you can help me while I tend to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[13565] = { id = 13565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twice Removed", description = "We cannot condone reckless violence - it is not our nature. However, there are times when the consequences of avoiding battle are too tangible to ignore, as is the case with these naga.\n\nWhen the earth in the area shattered, a small section of ruins rose to our east. These ruins once housed those loyal to Queen Azshara, and it seems her kind have returned in search of something.\n\nTake this petrified root. You can use it on their fallen to raise ents to aid you. Deal with them and their leader swiftly.", sourceObjective = "Use the Petrified Root to raise 6 Withered Ents and dispatch the naga leader, Lady Janira.", completion = "Thank you, ally. We shall keep a more vigilant eye should they return.", sourceObjectiveStatus = "unverified-source-field" }
quests[13566] = { id = 13566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Materials", description = "While we tend to Grimclaw, I would like you to peacefully gather some ritual materials for me from the nearby wildlife.\n\nI need whiskers from the moonstalkers to the west- pluck them from the sleeping ones and move away quickly.\n\nI need hair from the doe to the east, just avoid the stags.\n\nFinally, I need fur from the bears along the water to the northeast. Wait until they catch a fish, then get the sample quickly and get away before they finish eating.\n\nPlease do not harm any of them.", sourceObjective = "Retrieve 3 Moonstalker Whiskers, 3 Tufts of Mottled Doe Hair, and 3 Thistle Bear Fur.", progress = "Have you retrieved the materials that I asked for? And please tell me that you did not harm any of the animals in the process...", completion = "These will do perfectly. These are the final ingredients for an incense I've been working on. I will explain in just a moment, let me mix these in first.", sourceObjectiveStatus = "unverified-source-field" }
quests[13567] = { id = 13567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Stag", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Stag Spirit, take this incense to the woods just north of Bashal'Aran. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", sourceObjective = "Keeper Karithus has instructed you to receive the blessing of the Great Stag Spirit.", completion = "I am the caretaker for my kind, leading not through force, but through wisdom and swift action. Wisdom is what carries us into the deeper forest when danger beckons and swiftness is what leaves our enemies basking in our absence.\n\nIn this wisdom, I see through to your true intentions, and I know that you are deserving of my blessing, the blessing of my swiftness. It can be yours, but know that the other spirits will not welcome you once you proceed - consider this carefully before accepting my boon.", sourceObjectiveStatus = "unverified-source-field" }
quests[13568] = { id = 13568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Moonstalker", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Moonstalker Spirit, take this incense to the land just south of the Ruins of Lornesta. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", sourceObjective = "Keeper Karithus has instructed you to receive the blessing of the Great Moonstalker Spirit.", completion = "I share these forests willingly, accepting night elf kind into my home, and on occasion calling them friend. Though they have been tainted greatly in recent memory, I can see in you the same strength, honor, and spirit that first endeared them to me.\n\nIf you place value in the ferocity necessary to overcome all odds, then I am willing to call you my champion. Know now that if you side with my kind, the other spirits will not accept you, so consider your choice carefully.", sourceObjectiveStatus = "unverified-source-field" }
quests[13569] = { id = 13569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual Bond", description = "I will tend to Grimclaw until his rest is done - he will be ready to return very soon. I have one more task for you while we wait... a favor to grant you, really, should you recognize it.\n\nThe great wildlife spirits roam around us waiting and hoping for someone that will aid in stopping the destruction. They are with us as we speak even now, and with the materials  you brought me, I can grant you sight. Speak to these spirits, choose one, and return to me with their blessing.", sourceObjective = "Breathe in the incense in front of Keeper Karithus, and then choose the blessing of the Great Stag Spirit, the Great Thistle Bear Spirit, or the Great Moonstalker Spirit.\n\nKeep in mind that you can only receive the blessing of one spirit, so choose wisely.", completion = "So it is done. You have received the blessing of a great animal spirit, and I shall now complete the ritual for you. Please stand still.", sourceObjectiveStatus = "unverified-source-field" }
quests[13570] = { id = 13570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remembrance of Auberdine", sourceObjective = "I just want to offer my sincerest thanks for all that you've done for us. In my grief, I'm afraid that I didn't extend the gratitude that you truly deserve. We may not have made it here without you.\n\nKnow that you will always have friends here.\n\nAnd you needn't worry about my loneliness. Grimclaw has taken to keeping me company, and I have to say he's a more comforting companion than I would have expected.\n\nTake this, and go with all our blessings. Until we meet again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13571] = { id = 13571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletcher's Lost and Found", sourceObjective = "Above the stale, unwashed stench, you catch a whiff of a familiar smell!  It appears as if this once-mighty adventurer has a real love for kungaloosh.\n\nPeeking through the bars, you can barely make out the recipe written on his arm....", sourceObjectiveStatus = "unverified-source-field" }
quests[13572] = { id = 13572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jadefire Braziers", description = "The satyrs of Felwood have started pouring their hate and corruption into our lands. They have sent Sharax the Defiler to subdue parts of the forest that we Blackwood call home.\n\nIn addition to poisoning the land, animals, and plants, he has set up Jadefire braziers throughout the village to help extend his control over our people. Destroying the braziers alone won't be enough to stop him, but it will help lessen his influence while you work with Elder Brolg to free our brothers.", sourceObjective = "Gren Tornfur at Blackwood Hold wants you to destroy 8 Jadefire Braziers.", completion = "Thank you, {name}. With your efforts, we might be able to save the Blackwood who remain.", sourceObjectiveStatus = "unverified-source-field" }
quests[13573] = { id = 13573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion's Return", description = "It was only recently that we heard the news of Malfurion's awakening, mere moments before the Cataclysm occurred.\n\nAs soon as he regained consciousness, he gave a cryptic warning about the land splitting in two if something wasn't done and how all the shockwaves were converging here on Darkshore.\n\nHe then reportedly set off for somewhere in this vicinity.  I was sent here to find him, but I've found my hands full helping the refugees.\n\nPerhaps you could look for him to the southeast for us.", sourceObjective = "Look for Malfurion Stormrage at the Eye of the Vortex southeast of the Refugee Camp in Darkshore.", completion = "There is no time to waste, {class}.  It is taking every ounce of my power to keep Darkshore's entire landmass from being shattered and swept into the ocean... you must listen to me very carefully.", sourceObjectiveStatus = "unverified-source-field" }
quests[13575] = { id = 13575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land Is in Their Blood", description = "If we're to stabilize the forces of nature, we'll need every little bit of help we can get.  The furbolg of the Blackwood tribe have long inhabited the area and have strong ties to the land.\n\nTheir elder Shaman, Elder Brownpaw, wields great power over the elements -- his assistance would be invaluable.  See if you can obtain their aid.", sourceObjective = "Speak to Elder Brownpaw at the Blackwood Camp southwest of the Eye of the Vortex.", completion = "I have much respect for the great Malfurion Stormrage.  I cannot, however, leave my people in their time of need.  Maybe there is a way we can both help each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[13576] = { id = 13576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutual Aid", description = "With most of our brethren losing their way to madness or corruption, it would seem that we have little choice but to ally with you, {race}.  You can count on our aid... once you've proven we can count on yours.\n\nAs you can see, my people are having a bit of a problem with the fire elementals.  Help fight them and use this totem on their fiery remains.\n\nWe will return them to where they belong... whether they like it or not.", sourceObjective = "Use the Soothing Totem to absorb the remains of 8 Unbound Fire Elementals.", progress = "Is it done yet, {name}?", completion = "The element of fire is unique in that attacking it indiscriminately can often lead it to spreading further... succeeding only in agitating its flames.\n\nWe are wiser than that, {name}.  We are going to dispose of it properly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13577] = { id = 13577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Wildkin", description = "The wildkin were once numerous in Darkshore.  Such are their ties to the land that the Cataclysm that shattered Darkshore also decimated their numbers.\n\nThe wildkin Aroom is the last of his tribe and is a powerful elder with a strong connection to Elune.  His help will be most necessary in healing the land -- you will find him north of here at the Moontouched Den.", sourceObjective = "Speak to Aroom at the Moontouched Den north of the Eye of the Vortex.", completion = "A terrible sadness surrounds the creature.  Its eyes stare beyond you as you approach it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13578] = { id = 13578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aroom's Farewell", description = "<The creature hoots sadly as it addresses you.>\n\nAroom is last of tribe...\n\nOthers won't rest... need funeral pyre.  Bring Aroom the feathers of others.... let them rest.\n\nThen Aroom help you.", sourceObjective = "Obtain 8 Slain Wildkin's Feathers.", progress = "You bring others' feathers?", completion = "I thank you, {race}.  Soon my kin will rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13579] = { id = 13579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protector of Ameth'Aran", description = "Nothing will repair the land quicker than the strength of those who inhabit it.  We night elves are fortunate that some of our best allies just happen to be both the land and its inhabitants at once.\n\nThe Ancient of War known as Selenn was charged with guarding the ruins of Ameth'Aran, to the south.  Go there and seek his help.", sourceObjective = "Speak to Selenn at the Ruins of Ameth'Aran.", completion = "If the great Malfurion requires my presence, it is my duty to heed his call.  It is also my duty to protect these ruins, however.\n\nPerhaps you'll help me fulfill both my obligations, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13580] = { id = 13580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soothing the Elements", description = "Their fiery spirits are contained in the totem now.  Take it to the top of the Jagged Reef near the Blazing Strand and set it on the ground.\n\nThe totem's soothing energies will slowly wash over the elementals until their fury simmers down to calm.\n\nYou must protect the totem, for fire does not react favorably to the ritual of soothing.", sourceObjective = "Place the Charged Soothing Totem at the top of the reef near the Blazing Strand and protect it until the ritual is complete.", progress = "Is it done, {name}?", completion = "We are in your debt, {name}.  Perhaps now, with Malfurion's help, we can save the rest of Darkshore.", sourceObjectiveStatus = "unverified-source-field" }
quests[13581] = { id = 13581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackwood Pledge", description = "It won't be immediate, but the elementals' anger will soon die down and my people will live to fight another day.\n\nI will go help you and Malfurion in any way that I can.", sourceObjective = "Return to Malfurion Stormrage at the Eye of the Vortex.", completion = "This is fortunate news, {name}.  The furbolg may seem little more than a savage race, but their ties to the land are ancient and their shamans are second to none.", sourceObjectiveStatus = "unverified-source-field" }
quests[13582] = { id = 13582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Fire", description = "We need special flame for ritual.  We need Elune's fire.\n\nHoroo's spirit wanders east of here.  Horoo carries torch of Elune.  Bring here so spirits rest.\n\nAroom thanks you.", sourceObjective = "Obtain Elune's Torch from Horoo the Flamekeeper.", progress = "You have torch?", completion = "<Aroom lets out a long low-pitched hoot.>\n\nFinally kin may rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13583] = { id = 13583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wildkin's Oath", description = "Wildkin with Elune.  Aroom in your debt now.\n\nAroom help you now.  Return to Malfurion, I join you soon.", sourceObjective = "Return to Malfurion Stormrage at the Eye of the Vortex.", completion = "The wildkin were once the guardians of the land.  It is good to hear they haven't all forgotten their old ways.", sourceObjectiveStatus = "unverified-source-field" }
quests[13584] = { id = 13584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calming the Earth", description = "I would be neglecting my responsibility if I abandoned my post just now, with so many elementals out of control in the ruins.\n\nLet us deal with them first, before we see how we can aid Malfurion.  What do you say, small one?", sourceObjective = "Kill 8 Enraged Earth Elementals.", progress = "The land is deeply unsettled, {name}.  It'll be years before calm returns to these parts.", completion = "It's become clear, {name}.  The elements won't be calm until Malfurion succeeds in returning balance to the land.  Aiding him is, in a way, also fulfilling my task.", sourceObjectiveStatus = "unverified-source-field" }
quests[13585] = { id = 13585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sworn to Protect", description = "My duty here has been fulfilled as best it can.  Send word to Malfurion that I'll be joining him soon.\n\nGood luck to you, {name}.  Good luck to all of us.", sourceObjective = "Talk to Malfurion Stormrage at the Eye of the Vortex in Darkshore.", completion = "Excellent job, {name}!  Selenn's help in holding back the vortex will be invaluable.", sourceObjectiveStatus = "unverified-source-field" }
quests[13586] = { id = 13586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Dream", description = "Our efforts in containing the destruction don't appear to be quite enough.  I fear we're going to need aid from beyond the waking world.\n\nTwilight cultists inside the Earthshatter Cavern to the east have opened a gateway to a nightmare-infested section of the Emerald Dream.  They hold a green dragon prisoner named Thessera there.\n\nGo through the nightmare portal and free her.  She will be a powerful ally.", sourceObjective = "Step through the Nightmare Portal in the Earthshatter Cavern and speak to Thessera.", completion = "Malfurion calls?  Yes... I can hear his voice through the dream...", sourceObjectiveStatus = "unverified-source-field" }
quests[13587] = { id = 13587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waking Nightmare", description = "Malfurion's words are true, small one.  The rift that threatens to split Darkshore in half also threatens the separation between this world and yours.\n\nLet me aid you in any way that I can, lest further rifts between our worlds amplify the destruction taking place in both places.\n\nFirst you must undo the shackles cast upon me by retrieving the emerald scroll from the nightmare guardian that roams the halls below.", sourceObjective = "Obtain the Emerald Scroll from the Nightmare Guardian inside the Earthshatter Cavern.", progress = "Did you find it, {name}?", completion = "I thank you, {name}.  You've given me my freedom.  Let's see what we can do for your world now.", sourceObjectiveStatus = "unverified-source-field" }
quests[13588] = { id = 13588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of All Storms", description = "Twilight riders circle the skies above the vortex.  I fear it is their magic that has kept the cataclysmic forces from being contained by our efforts.\n\nTake to the skies with Thessera and destroy the riders and the portal from whence they came.", sourceObjective = "Ride Thessera to defeat 12 Twilight Riders and destroy the Twilight Portal.", progress = "Is it done, {name}?  I fear I cannot hold for much longer.", completion = "We are turning the tides, {name}.  We should be able to contain further damage.\n\nMuch work still remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13589] = { id = 13589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shatterspear Invaders", description = "If we didn't have enough on our hands with the land and the elements turning against us, it seems something has riled up the trolls to the northeast, and they've started on a war path. I'm not sure what their aims are, but they've already attacked several of our scouts and have besieged the cultists at the Tower of Althalaxx.\n\nWe've sent a contingent of our best Sentinels to counter their attacks. If you would travel northeast to the ruins and join them, I'm certain that they could use the extra hand.", sourceObjective = "Report to Lieutenant Morra Starbreeze at the Ruins of Mathystra.", completion = "Glynda sent you to lend a hand, did she? I'm glad she did - I could certainly use the help.\n\nI'm working on our initial plans to start whittling away at their ranks. Please feel free to help Tysha and Balthule in the meantime.", sourceObjectiveStatus = "unverified-source-field" }
quests[13590] = { id = 13590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Front Line", description = "Their forces are weakened, their supplies destroyed, and their subleaders are dead. It is time for us to take this fight to their home, and their leader. I'm admittedly still in the dark as to what spurred their sudden aggression, but perhaps we will find some answers on their doorstep.\n\nTake this arrow that Balthule prepared and report to Sandrya Moonfall deep in Shatterspear Vale to join the attack. It would be best to secure a ride on one of our nightsabers - going on foot would be dangerous.", sourceObjective = "Report to Huntress Sandrya Moonfall deep in Shatterspear Vale.", progress = "Greetings, {class}. Did you bring the arrow?", completion = "It is good to meet you. Word has been sent to me of the efforts you have made to aid us against the trolls, and I must admit I am a bit impressed. The final fight is upon us now, I hope you are prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[13591] = { id = 13591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing Connections", description = "The letter from Garrosh Hellscream makes clear the suspicions that were raised during the offensive on the Shatterspear. The presence of forsaken at the tower ruins and horde supplies and enforcers at the Shatterspear War Camp were only the start. Garrosh himself contacted the Shatterspear to spur their offensive towards Lor'danel, and it seems clear that he fully intends to push from the south as well.\n\nGlynda Nal'Shea will need this information if the night elves are to be prepared.", sourceObjective = "Bring the Hellscream's Missive to Ranger Glynda Nal'Shea at Lor'danel.", progress = "You're back! I hear the battle went well.", completion = "Well, this news is disturbing indeed. I will start dispatching messengers to Ashenvale immediately and see if we can't get some reinforcements prepared for them.\n\nI cannot thank you enough for all the help you've lent us in these trying times. Such heroic deeds deserve reward. I think I might have something that will serve you perfectly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13592] = { id = 13592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valiant's Field Training", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy.\n\nTravel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", sourceObjective = "Sir Marcus Barlowe at the Argent Tournament Grounds wants you to kill 10 Converted Heroes.", completion = "Welcome back from your exercises, {name}. Even while we practice for the competition, it's good to remind ourselves that the Scourge is still out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[13593] = { id = 13593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiant Of Stormwind", description = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Stormwind's tournament delegation?\n\nYou will train and rise through the ranks as you have before, but when you are named a champion of Stormwind, your squire will have the option of carrying our banner into battle.", sourceObjective = "Speak with Marshal Jacob Alerius again if you wish to become a valiant of Stormwind.", completion = "We are proud that you have agreed to train with us and compete on our behalf.", sourceObjectiveStatus = "unverified-source-field" }
quests[13594] = { id = 13594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget the Horde", description = "Evenar and the other apprentices may not be much use in a battle, but you look like you can more than hold your own. The Horde scum across the road to the east at Bathran's Haunt need to be taught a lesson.\n\nTheir new warlord, Garrosh Hellscream, has them up to no good. Feel like teaching them a thing or two?\n\nI'd come with you, but my assignment is to stay here and protect Orendil's apprentices, and that's exactly what I'm going to do.", sourceObjective = "Kill any 10 Horde at Bathran's Haunt.", completion = "<The sentinel eyes you appreciatively for a moment.>\n\nA job well done, {class}. If you're any indication of the quality of the {race} adventurers we're going to be seeing more of, we should have this war against the orcs and their Horde taken care of faster than expected.", sourceObjectiveStatus = "unverified-source-field" }
quests[13595] = { id = 13595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Their Own Design", description = "These creatures... these so-called Horde... they have cut me down in my prime and they are harvesting my hair for their evil plans.\n\nWill you help me to put an end to it, little {race}?\n\nI have overheard their herbalists speaking of something called wildfire upon their table across the way. If you were to take the bottle of this unnatural stuff and throw it at my corpse to the northeast, it would burn and no more of my hair will grow here.\n\nI am already dead and it is a small price to pay to stop them.", sourceObjective = "Obtain a Bottle of Wildfire and throw it at Bathran's Corpse to burn it.", progress = "Your lives are all so short. Why is it that you insist on squandering them by killing each other?", completion = "You have helped me to return to the ground, {name}.\n\nNow my hair will cease to sprout for these creatures. Better yet, I will be regrown all the sooner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13596] = { id = 13596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Plans", description = "We're not fully aware of the intentions of the Twilight's Hammer cultists to the southwest.  We fear an attack on Lor'danel, however their motives might go well beyond that.\n\nI need you to go to the Twilight Encampment and get your hands on their plans.  Hurry, {name}.  We might not have much time.", sourceObjective = "Obtain 6 Twilight Plans at the Twilight Encampment.", progress = "Have you obtained the plans yet, {name}?", completion = "Excellent job, {name}.  Now give me a moment to examine the plans you've brought me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13597] = { id = 13597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Thistle Bear", description = "In these woods reside three great spirits, that of the Stag, that of the Thistle Bear, and that of the Moonstalker. These spirits make powerful allies, but you can only align yourself with one of them.\n\nIf you wish to align yourself with the Great Thistle Bear Spirit, take this incense to a cave just east of the great whirlpool. Meditate before the great spirit while burning the incense on the ground between you, and face his trial to earn his blessing. Should you succeed, return to me.", sourceObjective = "Keeper Karithus has instructed you to receive the blessing of the Great Thistle Bear Spirit.", completion = "For countless ages I have walked these forests and lived in these mountains. Through snow and fire, I have watched civilizations crumble and nature press on. Now, the very earth turns against us, and it becomes very apparent that we must fight if our legacy is to continue.\n\nYour heart is true, and I would choose you as our champion. If you value the thick hide and resilience of my kind, then accept my boon. Know that the other spirits will not accept you once this choice is made, so choose wisely.", sourceObjectiveStatus = "unverified-source-field" }
quests[13598] = { id = 13598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsavory Remedies", description = "I have no doubts that Grimclaw will recover with the help of my healing magics, though I can't say the same for the poachers that attacked him. Still, I could use some salve to close his wounds and lessen his pain while he heals.\n\nTo the east you will find the Ruins of Lornesta. Among the crumbled stones, there is a variety of fuming toadstool that flourishes in the damp environment. Bring me some of the toadstools so that I can mix a salve for our friend here.", sourceObjective = "Recover 6 Fuming Toadstools.", progress = "Grimclaw is quite the fierce combatant. I feel somewhat sorry for those poachers, despite their aims.", completion = "You have my thanks, young one. We should be able to speed Grimclaw's recovery dramatically with this salve.", sourceObjectiveStatus = "unverified-source-field" }
quests[13599] = { id = 13599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimclaw's Return", description = "With the binding complete, the blessing has taken hold. It will most certainly make your travels in these lands easier.\n\nGrimclaw made a full recovery. Before I could do anything to stop him, he bolted off towards Lor'danel. I suppose that means it's time for your departure.\n\nIt was a great pleasure to have met you. For now, farewell - send my best wishes to Volcor and Grimclaw.", sourceObjective = "Return to Volcor and Grimclaw in Lor'danel.", completion = "You've returned! It is good to see you again. I suppose we have you to thank for Grimclaw's return?\n\nI'm afraid... I have some bad news. I've been unable to purge the toxin... their conditions worsen. Gershalla died shortly after you left, and Volcor... Volcor passed just before you came back.\n\nHe lived long enough to see Grimclaw come back safely, so he died with a smile on his face. I'm just sorry that I couldn't do more.\n\nFor now, I'm doing everything I can to save Shaldyn, so please excuse me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13600] = { id = 13600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Of all the times to have such rotten luck!\n\nMy tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Marshal Jacob Alerius at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "<The marshal accepts the Blade of Drak'Mar from you.>\n\nA fine weapon, and perfectly balanced. It will serve me well in the next match.", sourceObjectiveStatus = "unverified-source-field" }
quests[13601] = { id = 13601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Aid of the Refugees", description = "By Elune!  It appears that many of those we feared dead from the attack on old Auberdine have taken refuge in a camp outside the town ruins.\n\nThe cultists at the Twilight Encampment were planning on making quick work of them.  It's a good thing that you successfully attacked their position.\n\nSeek out Priestess Alinya at the Refugee Camp east of old Auberdine and far south of here.", sourceObjective = "Sentinel Lendra at Lor'danel wants you to speak to Priestess Alinya at the Refugee Camp.", completion = "I thank you for coming to our assistance.  As you can see, the refugees' situation is dire.", sourceObjectiveStatus = "unverified-source-field" }
quests[13602] = { id = 13602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga of the Strand", description = "There is evil lurking on the coast to the west.\n\nThe Zoram Strand is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas. It has been lost to the night elves for ages. Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know. But reason matters little; we must slay these fiends and throw them back to the depths!", sourceObjective = "Slay any 15 Wrathtail naga at the Zoram Strand.", completion = "Very well done, {name}. Your actions in the Zoram Strand against the naga are commendable.\n\nI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves. We know this, for we share a history with them.\n\nThe naga are cursed Highborne night elves. Ten thousand years ago, Queen Azshara made a pact of desperation with the Old Gods to save her surviving people from a watery grave.\n\nThe naga are the result of that pact.", sourceObjectiveStatus = "unverified-source-field" }
quests[13603] = { id = 13603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Marshal Jacob Alerius at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So the tales were true? This is a fine blade and I have no doubt that it will serve me well in the tournament. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13604] = { id = 13604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivum Data Disc", description = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections.  Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\"\n\nThere must be a device inside Ulduar capable of reading the disc.", sourceObjective = "Bring the Archivum Data Disc to the Archivum Console in Ulduar.", progress = "The console whirrs with energy as the round receptacle opens.", completion = "The platinum disc fits perfectly inside the console.  It begins to spin as its contents are scanned by white beams of light.", sourceObjectiveStatus = "unverified-source-field" }
quests[13605] = { id = 13605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Refugee", description = "There was this massive earthquake and then everything went black. The next thing I know, I woke up here a prisoner. The whole place is overrun with air elementals!\n\nI hope that everyone's okay. These Twillight's Hammer scum better not have hurt any of my friends!\n\nQuick, {class}, use something sharp to jimmy the lock on this ball and chain. Together we should be able to make it to the refugee camp.", sourceObjective = "Escort Archaeologist Hollee to safety", completion = "Aye, you're the fine lad who saved my Hollee!\n\nWell, I've got a fitting reward for you here, I'm sure. We really can't thank you enough for bringing her to safety, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13606] = { id = 13606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freya's Sigil", description = "Freya's Sigil is going to be one of the tougher ones, I reckon.\n\nAccording to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark.  Should any of the elders be harmed, the Sigil's integrity will be compromised.\n\nSparing the elders, however, means that Freya will be more powerful when you face her.\n\nWhat can I say, {name}.  We're stuck between a rock and hard place.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Freya's Sigil.\n\nFor more information on obtaining Freya's Sigil consult the Archivum Console.", progress = "Freya's sigil, {name}?  Do ye have it?", completion = "Excellent job, {name}.  We're one step closer to saving Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[13607] = { id = 13607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Celestial Planetarium", description = "Listen, <lad/lass>!  Azeroth's fate is at stake here.\n\nOur only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters.\n\nLocate the Celestial Planetarium and come back with any information you get.  We might still have some time to prepare for Algalon's arrival.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.", progress = "Did you find it, {name}?", completion = "It's locked?  Figures!\n\nLet's see what information this junk heap can give us...", sourceObjectiveStatus = "unverified-source-field" }
quests[13609] = { id = 13609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodir's Sigil", description = "Hodir's Sigil won't be easy to obtain.  Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it!\n\nCheck the Archivum console if you need more information.  That thing contains more knowledge than all of the world's libraries put together!", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Hodir's Sigil.\n\nFor more information on obtaining Hodir's Sigil, consult the Archivum Console.", progress = "Did ye obtain the sigil, {name}?", completion = "Ye did it!  I don't know how, but ye did!", sourceObjectiveStatus = "unverified-source-field" }
quests[13610] = { id = 13610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorim's Sigil", description = "Thorim's not himself, {name}.  He's come under a dark influence.\n\nAn evil presence under the guise of an illusion pretends to be his lost wife, Sif.\n\nYe can't let him be overcome by this impostor's spell.  If he does, the location of his sigil might forever be lost!\n\nYer going to have to beat some sense into him and yer going to have to do it quick.\n\nAs always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", sourceObjective = "Prospector Doren at the Archivum in Ulduar wants you to obtain Thorim's Sigil.\n\nFor more information on obtaining Thorim's Sigil consult the Archivum Console.", progress = "Well, {name}?  Do ye have it?", completion = "Ye never cease to impress, {name}.\n\nYe and me are having a pint together after all this is done, ye hear me?", sourceObjectiveStatus = "unverified-source-field" }
quests[13611] = { id = 13611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimiron's Sigil", description = "Mimiron's a clever one.  His entire abode is rigged with some sort of self-destruction mechanism.\n\nUnfortunately yer gonna have to race against it if ye want to get his sigil.  Check the Archivum Console for more details if ye need them.", sourceObjective = "Prospector Doren at the Ulduar Archivum wants you to obtain Mimiron's Sigil.\n\nFor more information on obtaining Mimiron's Sigil consult the Archivum Console.", progress = "Were you able to obtain the sigil, {name}?", completion = "I've got to hand it to you, {name}.  Our odds might not be the best, but I feel a lot better with you lending a hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[13612] = { id = 13612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Defense", description = "Lok'tar, {race}!\n\nThe campaign is finally underway! Soon, all of Ashenvale will be in the grip of the Horde.\n\nAs we expected, our offensive is forcing the enemy to test our defenses at every position.\n\nHere at Mor'shan, their assault has been decimated! But as the vice tightens, they will have no choice but to continue to press us here.\n\nScout the region, {class}. Search for night elf survivors and cut them down before they can regroup for another assault!", sourceObjective = "Kadrak at Mor'shan Ramparts wants you to kill 5 Ashenvale Skirmishers and 5 Ashenvale Bowmen.", progress = "Was your hunt successful, {race}?", completion = "Good work, {class}!\n\nYour efforts will help keep the enemy on their heels while our forces sweep across the land!", sourceObjectiveStatus = "unverified-source-field" }
quests[13613] = { id = 13613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Fallen", description = "Our forces are holding up admirably, {class}.\n\nBe that as it may, there are yet wounded to attend to - many still in the field of battle.\n\nI have created a salve that should grant the wounded enough energy to return to the ramparts for treatment. Please administer it to any in need before they become lost to us.", sourceObjective = "Use the Medicated Salve on 5 Wounded Mor'shan Defenders.", completion = "Thank you, {race}. I shall include your service to the Horde in my report.\n\nI should have these troops fit to fight again in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13614] = { id = 13614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Algalon", description = "You really did it, {name}.  Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium.\n\nYou best hurry, <lad/lass>.  Time is of the essence.", sourceObjective = "Bring the Sigils of the Watchers to the Archivum Console in Ulduar.", progress = "The console's bright lights scan the glass surface repeatedly, as if awaiting some form of input.", completion = "Stand by for verification.\n\nAccess to the Celestial Planetarium granted.  Please retrieve your key.", sourceObjectiveStatus = "unverified-source-field" }
quests[13615] = { id = 13615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empty Quivers", description = "Greetings, {class}, and welcome to the Ramparts.\n\nThings may appear a little chaotic here but do not worry. Kadrak has this juncture sealed up tight. Not a single elf has breached our lines!\n\nWhile you're here... I'm expecting a shipment of fresh supplies from Orgrimmar any day, but our watchmen are running dangerously low on arrows.\n\nBring me any you find and I will make it worth your trouble.", sourceObjective = "Truun at Mor'shan Ramparts wants you to collect 10 Serviceable Arrows from the Fallen Sky Lake region.", progress = "Have you collected the arrows we need, {class}?", completion = "Well done, {class}.\n\nThis should help get us by until our shipment arrives.", sourceObjectiveStatus = "unverified-source-field" }
quests[13616] = { id = 13616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "Curse that death knight for breaking my sword!\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Marshal Jacob Alerius at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade I seek?", completion = "The blade is as fine as the stories say. It would seem there's little reason to complete the repairs on my customary blade. Winter's Edge is far superior and I will continue to carry it. You have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13617] = { id = 13617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "West to the Strand", description = "{name}, I have a friend who could make good use of particular talents. His name is Talen and he's an archaeologist of sorts. Recently he's been fascinated with the upheaval of the old city of Zoram and its treasures.\n\nIf you're willing to lend him a hand, you can find him at the Blackfathom Camp down the path to the west.", sourceObjective = "Speak with Talen at the Blackfathom Camp in Ashenvale.", completion = "Hello, {class}.\n\nWhat's that? You say that Shyela sent you?\n\n\n\nVery well, let's get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[13618] = { id = 13618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Gorat!", description = "Gorat is one of the Horde's most adept assassins.\n\nThe mere mention of his name strikes fear into the hearts of our Alliance foes.\n\nHe is reliable, fiercely loyal, and - until now - punctual.\n\nSomething's not right, {class}.\n\nGorat's mission was to find and eliminate the elf in charge of this assault on the ramparts.\n\nHe should be somewhere in the region of Fallen Sky Lake.\n\nFind him!", sourceObjective = "Kadrak at Mor'shan Ramparts wants you to search the Fallen Sky Lake region for Gorat.", completion = "Listen carefully, {race}....", sourceObjectiveStatus = "unverified-source-field" }
quests[13619] = { id = 13619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Report", description = "<Gorat coughs deeply as he strains to speak.>\n\nIt was... an ambush....\n\nWe were... returning to the ramparts. All of us... lost....\n\nWe... discovered their leader... \n\n<Gorat painstakingly fills a vial with the blood spilling from one of his wounds.>\n\nMy men... must be avenged.... Bring this... to Kadrak....\n\nHe will know what to do....\n\n<Gorat expires.>", sourceObjective = "Gorat wants you to return the Vial of Gorat's Blood to Kadrak at Mor'shan Ramparts.", progress = "Did you find Gorat, {class}?!", completion = "<Kadrak listens intently as you share Gorat's last words.>\n\nIt is as I feared, then. May his rest be peaceful - only not yet!", sourceObjectiveStatus = "unverified-source-field" }
quests[13620] = { id = 13620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dinah, at Once!", description = "The Horde may have never known one more loyal than Gorat. He never failed to complete a mission, and it would seem that he refuses to allow this to be his first.\n\nGorat had you deliver this vial for a purpose. Dinah is the daughter of a revered shaman, and is more powerful than she appears. Bring her the vial and hope that we are not too late.", sourceObjective = "Kadrak wants you to bring the Vial of Gorat's Blood to Dinah at Mor'shan Ramparts.", progress = "What have you there, {race}?", completion = "Let's have a look, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13621] = { id = 13621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorat's Vengeance", description = "Fortune is with us this day, {race}.\n\nGorat's blood was fresh enough for me to conduct a special ritual taught to me as a child.\n\nUse this imbued blood on Gorat's corpse to summon forth his lingering spirit.\n\nDo his final bidding, then report back here to Kadrak.\n\nSpirits keep you safe, friend.", sourceObjective = "Use Gorat's Imbued Blood on Gorat's corpse, then defeat Captain Elendilad.", completion = "Well done, {race}.\n\nThe elf captain is dead and the soul of one of our beloved brethren can sleep in peace.\n\nI shall pass on word of your deeds to my superiors in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13622] = { id = 13622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient History", description = "The pieces fit together to form an elegant hammer.  Its construction appears to be at least partially Titan in nature.\n\nThe console inside the Archivum might have some information regarding this artifact.", sourceObjective = "Bring the Shattered Fragments of Val'anyr to the Archivum Console in the Archivum in Ulduar.", progress = "Awaiting input.", completion = "Analyzing fragments... please stand by.", sourceObjectiveStatus = "unverified-source-field" }
quests[13623] = { id = 13623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Orendil", description = "Quickly, {name}. I will put the Bathran's Hair into this bag, but you must deliver it to my master, Orendil Broadleaf. You will find him at Maestra's Post, just south down the road on the left.\n\nBut beware, we've received reports that the post is under attack from the Horde!", sourceObjective = "Deliver the Bag of Bathran's Hair to Orendil Broadleaf at Maestra's Post in Ashenvale.", progress = "You're a brave one to come here given the circumstances.\n\nWhat business have you, stranger?", completion = "So, Evenar was succesful. Actually, more to the point, YOU were successful.\n\nI cannot thank you enough, {class}, but there is more that must be done to the leaves before they will serve as a curative for what ails the child, Relara.", sourceObjectiveStatus = "unverified-source-field" }
quests[13624] = { id = 13624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Squad of Your Own", description = "I certainly hope that you're here to help, {class}. The situation is as dire as it appears. To put it quite simply, we are losing!\n\nMy girls and I are the last line of defense against the Horde, but we're not going to get out of this one without taking the fight to them. Up for a challenge?\n\nI have a small squad of sentinels that I can loan to you. Get them close and I'm certain that their magic arrows can destroy those wreckers and invaders.\n\nSpeak to me again if you need replacements.", sourceObjective = "Use a squad of Maestra's Post Sentinels to destroy 3 Ashenvale Wreckers and slay 10 Horde Invaders.", progress = "That's not nearly enough, {class}. We're about to lose our ground here and when that happens, it's all over for this section of the forest.\n\nWe must hold the line here!", completion = "I'd received a report about you from some of my scouts out in the forest but I had no idea how capable you are!\n\nThank you, {name}. With what you've accomplished the tide is turned. I've no doubt now that we'll rout them by the end of the day!", sourceObjectiveStatus = "unverified-source-field" }
quests[13625] = { id = 13625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning The Reins", description = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds.\n\nVisit the stables outside the pavilion, equip your lance, and mount up on the Quel'dorei steed. Familiarize yourself with the tactics available to you and use them to defeat the three different kinds of training dummies.", sourceObjective = "Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets and then return to Scout Shalyndria at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or the Silver Covenant Pavilion.", progress = "How goes the mounted combat practice?", completion = "Well done, {name}. Mounted combat is often hard to pick up for those accustomed to fighting on foot. I have no doubt that you'll continue to improve with practice, which is more than I can say for some warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[13626] = { id = 13626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respect for the Fallen", description = "There were two humans here: Feero Ironhand and Delgren the Purifier. They were members of a holy organization known as The Argent Dawn. Both fell defending the post when the Horde first attacked.\n\nI'm going to loan you my magical cloak. It was a gift from Cenarius that allows me to move invisibly.\n\nFind both of their corpses and retrieve Feero's hammer and Delgren's prayer book. Feero's corpse is in the courtyard and Delgren's is atop the tower.\n\nBeware, the warlock up there will be able to see you.", sourceObjective = "Retrieve Feero's Holy Hammer and The Purifier's Prayer Book.", progress = "Our losses here have been staggering.", completion = "I do not look forward to writing the letter to the Argent Dawn embassy in Darnassus. At least we'll be able to send their most prized possessions back for their loved ones.\n\nI cannot thank you enough for your courage, {name}. Please accept this on behalf of the post.", sourceObjectiveStatus = "unverified-source-field" }
quests[13627] = { id = 13627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jack Me Some Lumber", description = "Come closer. No, not too close. Don't want any unnecessary suspicion now, do we?\n\nThis coliseum requires more lumber than we've stockpiled and there's no way I'm going to pay to have it shipped in from Grizzly Hills. At the western end of Crystalsong Forest, by the Great Tree, grow a number of young Crystalsong oaks. They'd provide just the kind of planking we need for building and scaffolding. Take this axe, use it to fell the trees and then hew them into planks, but don't let anyone see you!", sourceObjective = "Bring 12 Rough Hewn Planks to Bezzle Blastbolt at the Argent Tournament Grounds.", progress = "Did you get the \"goods\" we talked about?", completion = "All excellent planks, and the price is right, too! Even better, those Argent Crusade sticks-in-the-mud will never know. They'll get their precious coliseum and I'll get my early completion bonus. Now that's a win-win if I ever saw one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13628] = { id = 13628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got Wood?", description = "Kadrak has just received fresh orders for our troops. I hear we're to begin offensive strikes into Ashenvale!\n\nI have far too few supplies to support an assault, and my shipment from Orgrimmar has yet to arrive.\n\nI am forced to  improvise, and could use your help, {class}.\n\nSpeak with Kadrak and ask him for the reins to Brutusk. The kodo will take you to the Warsong Labor Camp. Once there, seek out Gorka and ask her to load you up with logs.", sourceObjective = "Truun wants you to ride Brutusk to the Warsong Labor Camp.\n\nSpeak with Kadrak to get Kadrak's Reins to ride Brutus.", completion = "Welcome, {class}. It is good to see that the road to Mor'shan Ramparts remains clear.", sourceObjectiveStatus = "unverified-source-field" }
quests[13629] = { id = 13629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'anyr, Hammer of Ancient Kings", description = "The Archivum Console has hinted at a possible way to rebind the fragments of Val'anyr:  you must get the fragments inside the physical form of the being known as Yogg-Saron.\n\nIt sounds like a long shot, but for an artifact of such power you think the risk might just be worth it.", sourceObjective = "Throw the Shattered Pieces of Val'anyr into Yogg-Saron's maw while he's casting Deafening Roar and defeat Yogg-Saron and recover the Reforged Hammer of Ancient Kings.\n\nThis can only be completed in Heroic mode and only if at least one Ulduar Watcher is not assisting you.", progress = "Awaiting input.", completion = "Object integrity confirmed.  Please hold while solidified residue is removed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13630] = { id = 13630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reason Why", description = "The furbolg have descended from the heights and overrun the Ruins of Ordil'Aran to the north. I believe they did so because they were attracted to what the dead cultists there uncovered:  three moonstones.\n\nLiladris Moonriver will counsel you to deal with the furbolg in a more direct manner, and I will not gainsay her, but I would ask that you go to the ruins and deactivate the moonstones.", sourceObjective = "Deactivate the Blue, Green, and Red Moonstones.", completion = "Thank you, {name}.\n\nWith the moonstones of Ordil'Aran deactivated, we should not need to worry about any further incursions of furbolg here.\n\nHowever, my scouts have returned with disturbing news from the furbolg village. There is an imminent danger massing there.\n\nI wonder, might I entice you to carry a warning to Astranaar for me?", sourceObjectiveStatus = "unverified-source-field" }
quests[13631] = { id = 13631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Is Well That Ends Well", description = "We'd best hurry now, {name}.  We're going to have to transmit the reply-code from Dalaran.\n\nTake it to Rhonin, I will meet you there.", sourceObjective = "Take the Reply-Code Alpha to Rhonin in Dalaran.", progress = "You're ready, {name}?", completion = "You're here.  Let us hope this works.  For all our sakes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13632] = { id = 13632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rear Guard Duty", description = "The moon priestess has a plan to make sure that no further furbolg descend upon us from the highlands. I am more concerned with those that are already at the ruins, some of which are massing just outside of the post.\n\nDistasteful as it may be, I must ask that you head north into the Ruins of Ordil'Aran and slay the furbolg. We cannot fight on two fronts!\n\nThank you, {class}.", sourceObjective = "Slay any 10 furbolg at the Ruins of Ordil'Aran.", progress = "Ordil'Aran was a night elf city once long ago. It fell to ruins during the Sundering and only recently had some outsiders moved in to pillage it.\n\nNow they are dead, victims of their own curiosity that attracted the furbolg down upon them.", completion = "We are in your debt, {class}. If I know anything about the furbolg, they do not like their noses bloodied.\n\nIt won't be long now before they tuck tail and return to their village.", sourceObjectiveStatus = "unverified-source-field" }
quests[13633] = { id = 13633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight of Westfall?", description = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end.\n\nOf course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background.\n\nHe claims to be descended from the Cooper family of Westfall. Would you visit their residence in the western part of Moonbrook in Westfall? See if you can find any proof of his story.", sourceObjective = "Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings.", progress = "Have you found anything related to the Black Knight's story?", completion = "So you're saying this knight's story is a sham? Most suspicious. Dishonorable at the least, and murderous at the worst. Still, we can't confront him until we know for certain whether he was involved in these murders.\n\nDo nothing to arouse his suspicions, {name}. Discretion will serve us well as we continue to investigate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13634] = { id = 13634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight of Silverpine?", description = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end.\n\nOf course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background.\n\nHe claims to hail from Valgan's Field in Silverpine Forest. It's a small farm on the western shore of Lordamere Lake. Would you visit the farm and let me know if there's any truth to his story?", sourceObjective = "Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings.", progress = "Have you found anything related to the Black Knight's story?", completion = "So you're saying this knight's story is a sham? Most suspicious. Dishonorable at the least, and murderous at the worst. Still, we can't confront him until we know for certain whether he was involved in these murders.\n\nDo nothing to arouse his suspicions, {name}. Discretion will serve us well as we continue to investigate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13635] = { id = 13635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "South Gate Status Report", description = "We're due for sending a status report over to the mountaineers in the Valley of Kings.\n\nI expect you're on your way there next anyhow - would you mind dropping it off for me? Just take the tunnel to the east, and check in at the guard station. Hand it directly to Captain Rugelfuss.", sourceObjective = "Deliver Pilot Hammerfoot's Status Report to Captain Rugelfuss in the Valley of Kings.", progress = "What brings you all the way out here?", completion = "The South Gate status report? Excellent. I've been awaiting news from them for a while.\n\nWith the increasing number of troggs in the hills on all sides, I fear the outposts will be the first to feel any aggressive action.", sourceObjectiveStatus = "unverified-source-field" }
quests[13636] = { id = 13636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike's Orders", description = "I need to get some orders up to Mountaineer Stormpike at his post in Algaz Station. If you wouldn't mind taking them, just follow the road all the way up to the northwest and you'll be sure to see the main bunker.\n\nIf you'd like to lend a hand in accomplishing his tasks, we'd be glad to reward you for that as well.", sourceObjective = "Deliver Stormpike's Orders to Mountaineer Stormpike at Algaz Station.", completion = "Orders! Let's see what we have here... hah! He wants me to deal with the infestation of rat men. We're already in the middle of that, so no real deviation there.\n\nCare to lend a hand?", sourceObjectiveStatus = "unverified-source-field" }
quests[13637] = { id = 13637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ram Delivery", description = "The mountaineers at South Gate Outpost have requested a delivery of rams for their patrols. I didn't think we'd be able to spare any, but we can get them at least one thanks to you.\n\nMind riding it over and delivering it to Private Hammerfall for me? Just let me know when you're ready to go." }
quests[13638] = { id = 13638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Mountaineer", description = "You've proven yourself more than capable enough in a fight. I have something a bit more pressing to ask of you now.\n\nOne of my men, Mountaineer Gravelgaw, was captured by the troggs that we've been fighting in the southern mountains. Well, not so much captured as willingly gave himself up, but similar end result. I think he was hoping to identify their leader from the inside.\n\nI need you to go get him out. They'll probably be holding him near one of their upper caves deep in the mountains.", sourceObjective = "Captain Regulfuss at Thelsamar wants you to locate Mountaineer Gravelgaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[13639] = { id = 13639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resupplying the Excavation", description = "Ironband has an excavation to the southeast and he's been needing a hefty amount of explosives sent from the league for all the carving. Huldar, Miran, and Saean just departed with the most recent load and could probably use a hand.\n\nThey can't have made it very far, strong as they are. They can only move so fast laden down with those barrels.\n\nThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch. Go catch up with them and help'm out, will ya?", sourceObjective = "Locate Huldar, Miran, and Saean.", completion = "Hmph, it'll take more than a Dark Iron ambush to stop the deliveries!\n\nBut Saean... I would never have suspected him to be one of their sympathizers. We've been working with him for almost a year now... maybe I missed the signs.\n\nWell, I'll consider that later.", sourceObjectiveStatus = "unverified-source-field" }
quests[13640] = { id = 13640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Management Material", description = "Truun needs wood, huh? Normally I could provide, but not today.\n\nWith constant elf attacks, gathering lumber is dangerous work. The peons I have left are reluctant to venture into the woods.\n\nYou want wood? Then you go convince the peons to work.\n\nAnd keep them safe! I cannot afford to lose any more!", sourceObjective = "Convince Demoralized Peons to work and collect 5 bundles of Freshly Cut Wood.", progress = "Did you get the wood you need?", completion = "It seems you've solved one problem only to face another, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13641] = { id = 13641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seer's Crystal", description = "Now that we know there's no truth to the Black Knight's stories, we must find a way to connect him to the murdered knights.\n\nI know a way to reveal the truth about how they died, but it requires a rare material. We must gain a seer's crystal, found only among the unbound seers who congregate near night elf ruins in the Forlorn Woods in the central part of Crystalsong Forest. Find one of these seers, {name}, and bring me the crystal it holds.", sourceObjective = "Bring a Seer's Crystal to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Have you located a seer's crystal?", completion = "This one will do nicely. All that remains is to imbue it with the power of the Light, giving it the ability to find truth amid deception.", sourceObjectiveStatus = "unverified-source-field" }
quests[13642] = { id = 13642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bathed in Light", description = "The concoction is not quite complete; it must be bathed within the Light of Elune before we can even think about giving it to the child.\n\nThere is a known location just to the west at Lake Falathim where the goddess's moonlight always touches down, day or night. Please, {name}, I implore you for the sake of Relara, take the concoction and bathe it in Elune's radiance.\n\nBut beware, strange things have befallen the area of the lake, and I fear that it is no longer safe to go there.", sourceObjective = "Create a Bathed Concoction.", progress = "Did you have any trouble getting to the Light of Elune at Lake Falathim?", completion = "With the concoction blessed by the Light of Elune, it should be ready for delivery to Astranaar.\n\nThere is no time to waste, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13643] = { id = 13643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stories Dead Men Tell", description = "The crystal will reveal the truth about how three of the tournament's combatants died. Take it with you to the graveyard east of the Tournament Grounds and use it before the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip.\n\nIf indeed these men were murdered, then we must find a way to tie it to the Black Knight before he strikes again. Look closely at what the crystal tells you, {name}, for we must be certain these deaths were not accidental.", sourceObjective = "Use the Seer's Crystal at the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip to determine how they died, then return to Crusader Rhydalla.", progress = "Have you visisted the graves of the slain combatants?", completion = "So you say Lorien Sunblaze was done in by poison and Sir Wendell was burnt alive? Dreadful ways to die, both of them. Only Conall was killed by cold steel, and from your description, it was a coward's strike, not honorable combat that laid him in his grave.\n\nAll three sparred with and were scheduled to fight the Black Knight. This cannot be a coincidence. Now, we must find a way to prove it was the Black Knight's work.", sourceObjectiveStatus = "unverified-source-field" }
quests[13644] = { id = 13644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Which Has Risen", description = "When I sensed these... things... rising from below, I came to put them back down. I found the corpse of your friend and dragged him as far as I could before one of my fetlocks was broken. It is all that I can do to hold off these foul tendrils.\n\nThere is one that controls the tendrils and eyes. It calls itself Harbinger Aphotic -- I'm sure that you have heard it yelling from the south.\n\nThe harbinger stands out of range of my magic, but you could get to him. If you dare....", sourceObjective = "Slay Harbinger Aphotic.", progress = "The harbinger yet lives, {name}. I cannot begin to cleanse Lake Falathim until it is slain.", completion = "With the death of the harbinger, I can begin to cleanse the lake.\n\nYou have my deepest thanks, {name}. I mourn the loss of your friend, but know that his remains will fuel the reclamation of the forest hereabouts.", sourceObjectiveStatus = "unverified-source-field" }
quests[13645] = { id = 13645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Raene Wolfrunner", description = "I would ask you to deliver the gem directly to Raene Wolfrunner. Last I heard, she was still in Astranaar to the southeast.\n\nAt least the road between here and there is still relatively safe, so it should be a simple matter of following it there. Of course, if you'd rather, I believe that Sentinel Avana would be willing to loan you one of her nightsabers to swiftly make the trip.\n\nWhatever you choose, good health to you, {name}. May our paths cross again soon.", sourceObjective = "Deliver the Glowing Gem to Raene Wolfrunner at Astranaar in Ashenvale.", progress = "I am Raene Wolfrunner. Who might you be?", completion = "Teronis is dead?\n\n<The lady weeps softly for the loss of her friend and then composes herself after a moment.>\n\nWe must see to it that his sacrifice was not in vain. Are you willing to see this through, {class}?\n\nVery well, allow me some time to think about how we should proceed. I will know shortly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13646] = { id = 13646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astranaar Bound", description = "You have been of great assistance to us, {name}. Without you, we would have been wiped out by now.\n\nIt would be my pleasure to offer you one of my nightsabers anytime to ride to Astranaar up and to the southeast. I'm sure that you have very important business to attend to there.\n\nI would consider it a great kindness if you would speak with my sister, Sentinel Luara, when you arrive to tell her that I am well.\n\nJust speak to me again when you are ready to go, and anytime that you need a ride it is yours.", sourceObjective = "Speak with Sentinel Luara at Astranaar in Ashenvale.", completion = "Avana is alive?! I feared that she might be dead when we heard about the attack on Maestra's Post!\n\nAs you can see, we have our hands full with the Horde here as well.\n\nYou have given me the greatest gift by letting me know she is well. Any time that you wish to ride one of my nightsabers back to Maestra's Post, it is yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[13647] = { id = 13647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Hunt", description = "Well, you definitely have some fight in you.\n\nYou know, there are some hunter types at the lodge east of here, up in the hills - they might be right up your alley. Why don't you go pay them a visit and see if they have any work that you might be interested in?", sourceObjective = "Speak to Marek Ironheart at the Farstrider Lodge.", completion = "Hello there, laddy! The mountaineers sent you over, eh? I do suspect we might have just the sort of work you're looking for. Welcome to the Farstrider Lodge!", sourceObjectiveStatus = "unverified-source-field" }
quests[13648] = { id = 13648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Dark Iron Spy", description = "A dark iron spy has infiltrated the town, stolen documents from the Explorers' League establishment, and is now in hiding somewhere nearby. He was last sighted near the top of the hill to the south of town.\n\nA sizable reward awaits anyone who can bring this spy to justice. Dead or alive - dead preferred.", sourceObjective = "Slay Gorick Guzzledraught.", completion = "You brought that damned spy to justice! This is good news. We can all rest a little bit easier, not worrying about that one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13649] = { id = 13649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justin's Fun Test", description = "Hey there!  You look like you can handle your brew.  But can you handle your brew mug? \n\nThe Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let's see if you can toss one at old S.T.O.U.T. here.\n\nIt's easy, pick up a complimentary sampler and take a drink.  Just make sure you're facing S.T.O.U.T.  Talk to me after you've hit him 5 times.", sourceObjective = "Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Boxey Boltspinner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13650] = { id = 13650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Your Hands Off The Goods!", description = "We've uncovered some incredible artifacts at this site. It's hard to be convinced that it's all authentic, but there could be serious historical potential.\n\nUnfortunately, when the troggs overran the site, we lost access to three of our most notable finds to date. I'm concerned that the troggs might have stolen them or defiled them in our absence.\n\nIf you go into the excavation, find the Upturned Giant, the Overdressed Woman, and the Broken Tablet, and make sure they're still intact.", sourceObjective = "Inspect the Upturned Giant Artifact, the Overdressed Woman Artifact, and the Broken Tablet Artifact.", progress = "Are all of our artifacts still there? Are they damaged?", completion = "Woo! I'm relieved... I was worried they'd all be destroyed by now. Thank you for checking in on them.", sourceObjectiveStatus = "unverified-source-field" }
quests[13651] = { id = 13651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Needs a Little Oil", description = "You have your wood, but the encroaching elves have made it impossible for your kodo to return to Mor'shan Ramparts.\n\nI've dispatched a runner to Splintertree to summon aid. It shouldn't take long for their forces to clear the way.\n\nIn the meantime, I would ask that you do us a service. Rust has rendered our shredders inoperable. A little lubrication and they'll be as good as new.\n\nThe oil from the rotting slimes just north of here should work just fine.", sourceObjective = "Gorka at Warsong Labor Camp wants you to collect 5 Natural Oil from the Rotting Slimes in Ashenvale.", progress = "Were you able to collect the oil we need, {class}?", completion = "Thank you for the oil, {class}. Now prepare yourself!\n\nMy runner has returned with some desperate news....\n\nSplintertree is surrounded!", sourceObjectiveStatus = "unverified-source-field" }
quests[13652] = { id = 13652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense of the Stonewrought Dam", description = "We appreciate all of your help. We'll regain control of the excavation with a little bit of time, I'm just glad to know that all of our work wasn't destroyed in the process of this occupation.\n\nWe've been greedy enough with your time. I have a friend who could really use some of your help if you have any to lend. Go to the far side of the Loch and you'll find Stonewrought Dam. Once you're there, seek out Chief Engineer Hinderweir VII.", sourceObjective = "Seek out Chief Engineer Hinderweir VII at the Stonewrought Dam.", sourceObjectiveStatus = "unverified-source-field" }
quests[13653] = { id = 13653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crisis at Splintertree", description = "There will be no help coming from Splintertree.\n\nThe elves have launched a major assault on our stronghold there and they have the place surrounded!\n\nWe must inform Kadrak or die trying!\n\nYour kodo has been loaded up with the wood you collected. Let me know when you're ready and we'll charge the enemy lines.", sourceObjective = "Gorka wants you to accompany her to Mor'shan Ramparts and report to Kadrak.\n\nSpeak to her when you are ready to depart.", progress = "What's all this about, {class}?", completion = "Gorka...\n\nWe must always be prepared for losses. Her honorable service to the Horde will not be forgotten.\n\nAnd her sacrifice shall not be in vain!", sourceObjectiveStatus = "unverified-source-field" }
quests[13654] = { id = 13654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Something About the Squire", description = "Every day, the Black Knight's squire, Maloric, makes a big show of heading to Crystalsong Forest with his axe over his shoulder. He wants us to believe he's chopping wood, but he never returns with more than a few twigs.\n\nHe usually goes toward the ruins southwest of the Mirror of Twilight. He spends a lot of time out there, even for a squire with responsibilities to his knight.\n\nFind a way to distract or incapacitate him and search him. If he's up to something, we'll know it.", sourceObjective = "Obtain a Large Femur from a Skeletal Woodcutter and use it to incapacitate Maloric. Search Maloric for evidence, then report back to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Did the squire's behavior yield any clues?", completion = "<Crusader Rhydalla examines the bag's contents with a look of disgust on her face.>\n\nIt's all here, {name}: the poison that killed Lorien, a collection of knives, torches, and oil. No man has cause to possess these things here and no squire would do so without orders from his knightly master. We've found our murderer, {name}, but who is he working for?", sourceObjectiveStatus = "unverified-source-field" }
quests[13655] = { id = 13655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (2 of 6)", description = "The document bears the Explorers' League crest and seems to detail potential dig sites in Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Well look at that. You found one of our stolen documents!\n\nWe're much obliged for its return. Hopefully a bit of gold will suit your fancy for the finder's fee?", sourceObjectiveStatus = "unverified-source-field" }
quests[13656] = { id = 13656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (1 of 6)", description = "The document bears the Explorers' League crest and contains extensive information on the indigenous creatures of Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Hello, sonny! You seem to have found one of our stolen documents, eh?\n\nThank you kindly for bringing it back to us. We'll gladly lend some coin as thanks for its return.", sourceObjectiveStatus = "unverified-source-field" }
quests[13657] = { id = 13657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (3 of 6)", description = "The document bears the Explorers' League crest and contains historical records for all the notable locations in Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Our historical records! The thought of Dark Iron vermin delving into our past just made me sick to my stomach.\n\nWe appreciate you bringing this back to us. We'd like to offer you some coin as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[13658] = { id = 13658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (4 of 6)", description = "The document bears the Explorers' League crest and seems to detail transport routes utilized by the league into and out of Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Ug, I can't believe they got their hands on our transport routes - that was just asking for trouble!!\n\nThank you for getting this back to us before they were able to do much with it! You probably saved us a lot of heartache. Please accept some coin as a reward for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[13659] = { id = 13659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (6 of 6)", description = "The document bears the Explorers' League crest and contains detailed assessments of the various threats present within Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Hah! Think they got a kick out of seeing how low they were on our list of threat assessments? This document was admittedly a bit out of date, but none the less amusing.\n\nOf course, we'll offer you some money as a reward for returning this anyway - your efforts are appreciated!", sourceObjectiveStatus = "unverified-source-field" }
quests[13660] = { id = 13660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League Document (5 of 6)", description = "The document bears the Explorers' League crest and contains a detailed list of the artifacts excavated by Ironband's workers in southeastern Loch Modan. Sooty smudges lead you to believe it was likely stolen by the Dark Iron spies in the area.\n\nYou recall mention of missing documents at the Explorers' League building in Thelsamar.", sourceObjective = "Return the Explorers' League Document to Torren Squarejaw in Thelsamar.", completion = "Our artifact records! I was pretty well worried what the Dark Irons might try to steal with this information at their disposal.\n\nThank you for bringing this back to us. We'll gladly part with some coin to express our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[13661] = { id = 13661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heartfelt Appreciation", description = "You located all of our documents! We can't think you enough for the help... we'd all but given up hope that the dark irons would be able to act upon all of this information soon. It's good to know that they'll be left blind in their attacks for quite a while yet.\n\nTo thank you for all of your efforts on our behalf, we would like to offer you a gift. An artifact really... something we recovered from one of our digs. You have the appreciation of all of the Explorers' League.", sourceObjective = "You located all of our documents! We can't thank you enough for the help... we'd all but given up hope. It seemed sure that the Dark Irons would be able to act upon all of this information soon. It's good to know that they'll be left blind in their attacks for quite a while yet.\n\nTo thank you for all of your efforts on our behalf, we would like to offer you a gift. An artifact really... something we recovered from one of our digs. You have the appreciation of all of the Explorers' League.", sourceObjectiveStatus = "unverified-source-field" }
quests[13662] = { id = 13662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining Acceptance", progress = "You've worked your way up through the Brotherhood's corporate hierarchy, {race}. We have begun to look favorably upon you. Quite an accomplishment!\n\nIf you're interested in more work and earning more respect amongst us, listen up.\n\nWe can refine the fiery flux by adding a simple Dark Iron residue to the mix. The Dark Iron residue can be found in Blackrock Depths.\n\nBring me all the Dark Iron residue you find!", completion = "Keep the residue pouring in!" }
quests[13663] = { id = 13663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Orders", description = "We must discover who sent the Black Knight to the tournament and what his master hopes to gain by killing the competitors.\n\nThe Kirin Tor has offered to help in this matter and provided us with something to help our search.\n\nTake this enchanted bridle to the Black Knight's camp on the eastern edge of the tournament grounds and use it to gain control over the Black Knight's gryphon. The bridle's magic will force the gryphon to take you to his master's home. Search it and return with anything you find.", sourceObjective = "Use the Enchanted Bridle to gain control of the Black Knight's Gryphon and ride it to its destination. Once you have arrived, recover the Stolen Tournament Invitation and the Black Knight's Orders and bring them to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "What did you discover?", completion = "<Crusader Rhydalla's face pales as she reads the orders.>\n\nThis can only mean one thing, {name}. The Black Knight is a member of the Cult of the Damned and has been sent by Arthas to disrupt the tournament!\n\nThe Black Knight has proven himself a fearsome combatant, and you will need to be every bit as good if you wish to face him. When you are a champion, return to me and we'll find a way to ensure his defeat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13664] = { id = 13664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Fall", description = "We must put an end to the Black Knight's scheming, and show those who oppose us that we will not stand by and allow our champions to be murdered.\n\nBy now, he will suspect that someone is on his trail. Challenge him in the light of day, where he cannot refuse or murder in the dark, {name}.\n\nUse my argent charger for the battle. It's housed in the stables.\n\nSpeak to Squire Cavin at the Ring of Champions. The squire will call the Black Knight to battle, but you will make him answer for his crimes.", sourceObjective = "Defeat the Black Knight and then speak to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Is it done?", completion = "With the death of the Black Knight, the tournament may once again serve its purpose. The champions of the Horde and Alliance may demonstrate their skill at arms and train for the day when Arthas and his minions will no longer threaten us.\n\nYou have the thanks of the Argent Crusade, {name}, and that of all who have answered our call.", sourceObjectiveStatus = "unverified-source-field" }
quests[13665] = { id = 13665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Melee", description = "The grand melee is the most important of the tournament's competitions. The people of Stormwind adore their knights and are looking forward to seeing us win the melee. To that end, they've been honing their skills against the other valiants.\n\nI suggest you do the same.\n\nGo to the stables outside the pavilion, equip your lance, mount the stabled Elwynn steed, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", sourceObjective = "Bring 3 Marks of the Valiant to Captain Joseph Holley at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", progress = "Have you completed your training for the grand melee?", completion = "Well done. Training against the other valiants is one of the best ways to prepare yourself for tournament competition. I know you'll make Stormwind proud, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13666] = { id = 13666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Arcanist Taelis at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So there is some truth to those old tales? It seems they did not lie about the quality of the blade. Well done, {name}. The champion who wields it will be a lucky man, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13667] = { id = 13667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Argent Tournament", description = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy.\n\nArcanist Taelis is the Silver Covenant's representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Alliance tent in the northeastern part of the grounds.", sourceObjective = "Speak with Arcanist Taelis at the Argent Tournament grounds to enroll in the tournament.", completion = "I have entered your name in the rolls, {name}. As an aspirant you will train with others who wish to compete in the tournament and hone your mounted combat skills. Once you have proven yourself, you will be allowed to enter the lowest rank of competition on behalf of your capital city.", sourceObjectiveStatus = "unverified-source-field" }
quests[13668] = { id = 13668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Argent Tournament", description = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy.\n\nMagister Edien Sunhollow is the Sunreaver representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Horde tent in the southeastern part of the grounds.", sourceObjective = "Speak with Magister Edien Sunhollow at the Argent Tournament grounds to enroll in the tournament.", completion = "I have entered your name in the rolls, {name}. As an aspirant you will train with others who wish to compete in the tournament and hone your mounted combat skills. Once you have proven yourself, you will be allowed to enter the lowest rank of competition on behalf of your capital city.", sourceObjectiveStatus = "unverified-source-field" }
quests[13669] = { id = 13669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Our champions have taken a liking to ancient weapons produced here in Northrend.\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Arcanist Taelis at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "There's no doubt that this is a blade of exquisite quality and balance. Now I understand why these weapons are so coveted among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13670] = { id = 13670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "The Ironforge grand champion's squire told me an intriguing story.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Arcanist Taelis at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the squire said it would be, but where did he find out about it? No matter; it will serve its new owner well. Perhaps it's only fair that Ironforge's grand champion be the one to wield it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13671] = { id = 13671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training In The Field", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament.\n\nTravel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", sourceObjective = "Avareth Swiftstrike at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment.", progress = "Have you tested yourself in combat against the Scourge?", completion = "You have shown yourself a capable combatant, {name} and you will serve as an example to the rest of the aspirants who clamor to compete on behalf of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13672] = { id = 13672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up To The Challenge", description = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant.\n\nWhen you are ready to begin the challenge, return to me.", sourceObjective = "Present Arcanist Taelis at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge.", progress = "Do you wish to take the aspirant's challenge?", completion = "Very well, I will make the arrangements.", sourceObjectiveStatus = "unverified-source-field" }
quests[13673] = { id = 13673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blade Fit For A Champion", description = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons.\n\nThere's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, {name}. Otherwise, you'll catch warts.", sourceObjective = "Retrieve the Ashwood Brand and bring it to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Were you able to recover the blade?", completion = "So there is some truth to those old tales? It seems they did not lie about the quality of the blade. Well done, {name}. The champion who wields it will be a lucky man, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13674] = { id = 13674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Weapon", description = "Our champions have taken a liking to ancient weapons produced here in Northrend.\n\nI've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", sourceObjective = "Bring the Blade of Drak'Mar to Magister Edien Sunhollow at the Argent Tournament Grounds.", progress = "Were the wandering bard's tales true? Have you brought a blade?", completion = "There's no doubt that this is a blade of exquisite quality and balance. Now I understand why these weapons are so coveted among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13675] = { id = 13675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edge Of Winter", description = "I heard an interesting story from one of the Orgrimmar valiants.\n\nIn southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse.\n\nBring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her.\n\nProve your worth and earn the weapon that she has guarded for so long, {name}.", sourceObjective = "Magister Edien Sunhollow at the Argent Tournament Grounds wants you to bring him Winter's Edge.", progress = "Did you win the blade?", completion = "The blade is as fine as the valiant said it would be, but where did he find out about it? No matter; it will serve its new owner well. Perhaps it's only fair that Orgrimmar's grand champion be the one to wield it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13676] = { id = 13676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training In The Field", description = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament.\n\nTravel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", sourceObjective = "Amariel Sunsworn at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment.", progress = "Have you tested yourself in combat against the Scourge?", completion = "You have shown yourself a capable combatant, {name} and you will serve as an example to the rest of the aspirants who clamor to compete on behalf of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13677] = { id = 13677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning The Reins", description = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds.\n\nVisit the stables outside the pavilion, equip your lance, and mount up on the Sunreaver hawkstrider. Familiarize yourself with the mount and use its abilities to defeat the three different kinds of training dummies.", sourceObjective = "Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets, and then return to Galathia Brightdawn at the Argent Tournament Grounds.\n\nIf you lose your lance, you can get another from any of the Lance Racks near the stables or the Sunreaver Pavilion.", progress = "How goes the mounted combat practice?", completion = "Well done, {name}. Mounted combat is often hard to pick up for those accustomed to fighting on foot. I have no doubt that you'll continue to improve with practice, which is more than I can say for some warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[13678] = { id = 13678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up To The Challenge", description = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant.\n\nWhen you are ready to begin the challenge, return to me.", sourceObjective = "Present Magister Edien Sunhollow at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge.", progress = "Do you wish to take the aspirant's challenge?", completion = "Very well, I will make the arrangements.", sourceObjectiveStatus = "unverified-source-field" }
